    AP2.press(mix, {fn: () => AP2.router.go('trainer/mix'), label: 'Täglichen Mix starten', base: (c) => ({backgroundColor: c.accent, color: c.onAccent, boxShadow: S.shadow}), hover: () => ({opacity: '0.92'})});
