// viz/lib.js
// Diagramm-Generatoren für wiederkehrende Layouts (Kette, Spalte, Zyklus, Baum, Schichten).
(function () {
  const chain = (labels, o, vertical) => {
    const opt = o || {};
    const count = labels.length;
    const w = opt.w || (vertical ? 420 : 720);
    const gap = opt.gap || 56;
    const nh = opt.nh || 48;
    const nw = vertical ? (opt.bw || 260) : Math.min(opt.bw || 150, (w - 40) / count - 22);
    const h = opt.h || (vertical ? 24 + count * (nh + gap) - gap : 110);
    const stepX = (w - 40 - nw) / Math.max(1, count - 1);
    const nodes = labels.map((t, i) => ({id: 'n' + i, t, w: nw, h: nh, k: opt.k || 'round', s: (opt.styles || [])[i] || 'plain',
      x: vertical ? w / 2 : 20 + nw / 2 + i * stepX, y: vertical ? 12 + nh / 2 + i * (nh + gap) : h / 2}));
    // Kantentexte stehen bei waagerechten Ketten über den Kästen: im schmalen Zwischenraum würden sie die Kästen überdecken.
    const edges = nodes.slice(1).map((n, i) => ({a: 'n' + i, b: 'n' + (i + 1), t: (opt.edgeText || [])[i],
      lo: vertical ? null : [0, -(nh / 2 + 11)], mw: vertical ? w - 20 : stepX - 10}));
    return {w, h, nodes, edges, cap: opt.cap};
  };
  const cycle = (labels, o) => {
    const opt = o || {};
    const w = opt.w || 720;
    const h = opt.h || 380;
    const rx = opt.rx || 250;
    const ry = opt.ry || 130;
    const count = labels.length;
    const nodes = labels.map((t, i) => {
      const ang = -Math.PI / 2 + (2 * Math.PI * i) / count;
      return {id: 'c' + i, t, x: w / 2 + rx * Math.cos(ang), y: h / 2 + ry * Math.sin(ang), k: opt.k || 'round', s: (opt.styles || [])[i] || 'plain'};
    });
    const edges = nodes.map((n, i) => ({a: n.id, b: 'c' + ((i + 1) % count), t: (opt.edgeText || [])[i]}));
    return {w, h, nodes, edges, cap: opt.cap};
  };
  const tree = (root, o) => {
    const opt = o || {};
    const gx = opt.gx || 64;
    const gy = opt.gy || 72;
    const nodes = [];
    const edges = [];
    let leaf = 0;
    let depth = 0;
    const walk = (spec, level, parent) => {
      if (spec.e) { const ghost = {x: 40 + leaf * gx}; leaf++; return ghost; }
      const rec = {id: 't' + nodes.length, t: spec.t, y: 32 + level * gy, k: opt.k || 'circle', s: spec.s || 'plain', w: opt.w || 42, h: opt.h || 42};
      nodes.push(rec);
      depth = Math.max(depth, level);
      if (parent) edges.push({a: parent.id, b: rec.id, ea: 'none'});
      const kids = (spec.c || []).map((child) => walk(child, level + 1, rec));
      if (kids.length) rec.x = (kids[0].x + kids[kids.length - 1].x) / 2;
      else { rec.x = 40 + leaf * gx; leaf++; }
      return rec;
    };
    walk(root, 0, null);
    return {w: Math.max(opt.minW || 0, 80 + (leaf - 1) * gx), h: 64 + depth * gy, nodes, edges, cap: opt.cap};
  };
  const layers = (rows, o) => {
    const opt = o || {};
    const w = opt.w || 720;
    const rh = opt.rh || 50;
    const lw = opt.lw || 250;
    const nodes = [];
    rows.forEach((row, i) => {
      const y = 12 + rh / 2 + i * (rh + 8);
      nodes.push({id: 'l' + i, x: 12 + lw / 2, y, w: lw, h: rh, t: row[0], s: row[2] || 'accent', k: 'round', b: true});
      nodes.push({id: 'r' + i, x: 12 + lw + 12 + (w - lw - 36) / 2, y, w: w - lw - 36, h: rh, t: row[1], s: 'soft', k: 'round'});
    });
    return {w, h: 24 + rows.length * (rh + 8) - 8, nodes, edges: [], cap: opt.cap};
  };
  AP2.dg = {flow: (l, o) => chain(l, o, false), col: (l, o) => chain(l, o, true), cycle, tree, layers};
})();
;
// viz/gantt.js
// Gantt-Diagramm aus Daten: Zeilen [name, start, dauer, stil], Abhängigkeiten [von, nach].
(function () {
  const build = (tasks, o) => {
    const opt = o || {};
    const left = opt.left || 150;
    const total = opt.total;
    const unit = opt.unit || 24;
    const row = 34;
    const w = left + total * unit + 24;
    const h = 40 + tasks.length * row + 12;
    const nodes = [];
    const edges = [];
    for (let t = 0; t <= total; t += opt.tick || 1) {
      const x = left + t * unit;
      edges.push({a: [x, 30], b: [x, h - 8], ea: 'none', s: 'border', w: 1});
      nodes.push({id: 'tk' + t, k: 'text', x, y: 16, t: opt.tickLabel ? opt.tickLabel(t) : String(t), fs: 11, tc: 'text3', w: 20, h: 14});
    }
    const pos = tasks.map((task, i) => ({x0: left + task[1] * unit, x1: left + (task[1] + task[2]) * unit, y: 40 + i * row + row / 2}));
    tasks.forEach((task, i) => {
      const p = pos[i];
      nodes.push({id: 'nm' + i, k: 'text', x: left - 10, y: p.y, t: task[0], fs: 12, tc: 'text', w: 10, h: 10, anchorEnd: true, mw: left - 18});
      if (task[2] === 0) nodes.push({id: 'b' + i, k: 'diamond', x: p.x0, y: p.y, w: 18, h: 18, s: 'solid', t: ''});
      else nodes.push({id: 'b' + i, k: 'round', x: (p.x0 + p.x1) / 2, y: p.y, w: p.x1 - p.x0, h: 22, s: task[3] || 'accent', t: opt.labels ? String(task[2]) : '', fs: 11});
    });
    (opt.deps || []).forEach(([from, to]) => {
      const a = pos[from];
      const b = pos[to];
      const via = a.y === b.y ? [] : [[a.x1 + 8, a.y], [a.x1 + 8, b.y]];
      edges.push({a: [a.x1, a.y], b: [b.x0, b.y], via, s: 'text3', w: 1.2});
    });
    return {w, h, nodes, edges, cap: opt.cap, keep: opt.keep};
  };
  AP2.dg.gantt = build;
})();
;
// viz/venn.js
// Venn-Diagramm für JOIN-Arten: Mengen A und B, markierter Bereich je nach Modus.
(function () {
  const {h, svg, st} = AP2;
  const S = AP2.S;
  const W = 240;
  const H = 150;
  const CA = 92;
  const CB = 148;
  const R = 58;
  const MODES = {
    inner: {fillA: false, fillB: false, inter: true}, left: {fillA: true, fillB: false, inter: true}, right: {fillA: false, fillB: true, inter: true},
    full: {fillA: true, fillB: true, inter: true}, leftOnly: {fillA: true, fillB: false, inter: false}, rightOnly: {fillA: false, fillB: true, inter: false},
    outer: {fillA: true, fillB: true, inter: false},
  };
  const circle = (cx, paintFn, o, extra) => paintFn(svg('circle', Object.assign({cx, cy: 70, r: R}, extra || {})), o);
  const figure = (mode, label, sub) => {
    const root = svg('svg', {viewBox: '0 0 ' + W + ' ' + H, role: 'img', 'aria-label': label});
    st(root, {width: '100%', height: 'auto', display: 'block', fontFamily: S.font.sans});
    const paint = AP2.paint(root);
    const m = MODES[mode];
    const id = 'vc' + Math.floor(Math.random() * 1e9);
    const clip = svg('clipPath', {id}, [svg('circle', {cx: CA, cy: 70, r: R})]);
    root.appendChild(clip);
    if (m.fillA) root.appendChild(circle(CA, paint, {f: 'accent'}));
    if (m.fillB) root.appendChild(circle(CB, paint, {f: 'accent'}));
    if (m.inter && !m.fillA && !m.fillB) root.appendChild(circle(CB, paint, {f: 'accent'}, {'clip-path': 'url(#' + id + ')'}));
    if (!m.inter) root.appendChild(circle(CB, paint, {f: 'surface'}, {'clip-path': 'url(#' + id + ')'}));
    if (m.inter && m.fillA !== m.fillB && (m.fillA || m.fillB)) root.appendChild(circle(CB, paint, {f: 'accent'}, {'clip-path': 'url(#' + id + ')'}));
    root.appendChild(circle(CA, paint, {s: 'line', sw: 2}));
    root.appendChild(circle(CB, paint, {s: 'line', sw: 2}));
    AP2.shapes.text(root, paint, CA - 22, 70, 'A', {size: 18, bold: true, color: 'text', halo: true});
    AP2.shapes.text(root, paint, CB + 22, 70, 'B', {size: 18, bold: true, color: 'text', halo: true});
    const cap = AP2.tint(h('div', {text: label, style: {fontWeight: S.fw.semi, fontSize: S.f.sm, textAlign: 'center'}}), 'text');
    const subEl = AP2.tint(h('div', {text: sub || '', style: {fontSize: S.f.xs, textAlign: 'center'}}), 'text2');
    return h('div', {style: {flex: '1 1 200px', padding: S.sp[3], border: '1px solid', borderRadius: S.r.md, margin: '0 0 ' + S.sp[3]}}, [root, cap, subEl]);
  };
  AP2.blocks.venn = (items) => {
    const row = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[3]}}, items.map((it) => figure(it[0], it[1], it[2])));
    row.querySelectorAll(':scope > div').forEach((el) => AP2.theme.bind(el, (n, c) => { n.style.backgroundColor = c.surface; n.style.borderColor = c.border; }));
    return row;
  };
})();
;
// viz/nsd.js
// Struktogramm (Nassi-Shneiderman): rekursiver Aufbau aus act, if, while, for, until, case.
(function () {
  const AH = 34;
  const IH = 48;
  const LH = 30;
  const IND = 26;
  const seqH = (list, w) => list.reduce((sum, it) => sum + height(it, w), 0);
  const height = (it, w) => {
    const kind = it[0];
    if (kind === 'act') return AH;
    if (kind === 'if') return IH + Math.max(seqH(it[2], w / 2), seqH(it[3] || [], w / 2), AH);
    if (kind === 'case') return IH + 24 + Math.max(...it[2].map((c) => seqH(c[1], w / it[2].length)));
    return LH + seqH(it[2], w - IND);
  };
  const make = (out) => ({
    rect: (x, y, w, h, t, s) => out.nodes.push({id: 'q' + out.nodes.length, k: 'box', x: x + w / 2, y: y + h / 2, w, h, t: t || '', s: s || 'clear', fs: 12}),
    text: (x, y, t, bold, mw) => out.nodes.push({id: 'q' + out.nodes.length, k: 'text', x, y, t, w: 10, h: 10, fs: 12, b: bold, mw}),
    line: (a, b) => out.edges.push({a, b, ea: 'none', w: 1.2}),
  });
  const layout = (list, x, y, w, g, fill) => {
    let cur = y;
    list.forEach((it) => { cur += one(it, x, cur, w, g); });
    if (fill && cur < y + fill) { g.rect(x, cur, w, y + fill - cur, ''); cur = y + fill; }
    return cur - y;
  };
  const one = (it, x, y, w, g) => {
    const kind = it[0];
    const total = height(it, w);
    if (kind === 'act') g.rect(x, y, w, AH, it[1]);
    else if (kind === 'if') {
      g.rect(x, y, w, IH, '');
      g.line([x, y], [x + w / 2, y + IH]); g.line([x + w, y], [x + w / 2, y + IH]);
      g.text(x + w / 2, y + 13, it[1], true, w * 0.64); g.text(x + 24, y + IH - 12, 'Ja'); g.text(x + w - 28, y + IH - 12, 'Nein');
      layout(it[2], x, y + IH, w / 2, g, total - IH);
      layout(it[3] || [], x + w / 2, y + IH, w / 2, g, total - IH);
    } else if (kind === 'case') {
      const cw = w / it[2].length;
      g.rect(x, y, w, IH, ''); g.text(x + w / 2, y + 13, it[1], true, w - 16);
      it[2].forEach((c, i) => {
        g.line([x + i * cw, y + IH], [x + i * cw, y + total]);
        g.rect(x + i * cw, y + IH, cw, 24, c[0], 'soft');
        layout(c[1], x + i * cw, y + IH + 24, cw, g, total - IH - 24);
      });
    } else if (kind === 'until') {
      g.rect(x, y, IND, total - LH, '', 'soft');
      layout(it[2], x + IND, y, w - IND, g, 0);
      g.rect(x, y + total - LH, w, LH, it[1]);
    } else {
      g.rect(x, y, w, LH, it[1]);
      g.rect(x, y + LH, IND, total - LH, '', 'soft');
      layout(it[2], x + IND, y + LH, w - IND, g, 0);
    }
    return total;
  };
  AP2.dg.nsd = (items, o) => {
    const opt = o || {};
    const w = opt.w || 520;
    const out = {nodes: [], edges: []};
    const h = layout(items, 10, 10, w, make(out), 0);
    return {w: w + 20, h: h + 20, nodes: out.nodes, edges: out.edges, cap: opt.cap, keep: opt.keep};
  };
})();
;
// viz/seq.js
// Sequenzdiagramm: Lebenslinien und Nachrichten (auch für Protokolle wie TLS oder Kerberos).
(function () {
  const {h, svg, st} = AP2;
  const S = AP2.S;
  const GAP = 44;
  const TOP = 92;
  const idxOf = (cfg, ref) => (typeof ref === 'number' ? ref : cfg.actors.indexOf(ref));
  // room: Platz bis zur nächsten Lebenslinie, damit sich die Köpfe nicht überdecken.
  const header = (g, paint, x, name, room) => {
    const width = Math.min(Math.max(110, name.length * 8 + 28), room);
    g.appendChild(paint(svg('rect', {x: x - width / 2, y: 12, width, height: 36, rx: 6}), {s: 'accent', f: 'accentSoft', sw: 1.5}));
    AP2.shapes.text(g, paint, x, 30, name, {bold: true, max: width - 12});
  };
  const arrow = (g, paint, x1, x2, y, kind) => {
    g.appendChild(paint(svg('line', {x1, x2, y1: y, y2: y}), {s: 'line', sw: 1.5, dash: kind === 'r' ? '6 4' : null}));
    AP2.marks.describe(kind === 'a' || kind === 'r' ? 'open' : 'arrow', [x2, y], [x1, y])
      .forEach((d) => g.appendChild(paint(svg(d.tag, d.a), Object.assign({s: 'line', f: null, sw: 1.5}, d.o))));
  };
  const selfCall = (g, paint, x, y, label, room) => {
    g.appendChild(paint(svg('path', {d: 'M' + x + ' ' + (y - 8) + 'h30v16h-30'}), {s: 'line', sw: 1.5}));
    AP2.marks.describe('arrow', [x, y + 8], [x + 12, y + 8]).forEach((d) => g.appendChild(paint(svg(d.tag, d.a), Object.assign({s: 'line', f: null, sw: 1.5}, d.o))));
    AP2.shapes.text(g, paint, x + 38, y, label, {anchor: 'start', size: 12, color: 'text2', halo: true, max: room});
  };
  // Notizen bleiben innerhalb der Zeichenfläche (total: Breite des Diagramms).
  const note = (g, paint, x, y, txt, total) => {
    const width = Math.min(txt.length * 7 + 24, total - 16);
    const cx = Math.min(Math.max(x, 8 + width / 2), total - 8 - width / 2);
    g.appendChild(paint(svg('rect', {x: cx - width / 2, y: y - 14, width, height: 28, rx: 4}), {s: 'line', f: 'surface2', sw: 1.2}));
    AP2.shapes.text(g, paint, cx, y, txt, {size: 12, max: width - 12});
  };
  const sep = (g, paint, width, y, txt) => {
    g.appendChild(paint(svg('line', {x1: 16, x2: width - 16, y1: y, y2: y}), {s: 'accent', sw: 1.2, dash: '3 4'}));
    AP2.shapes.text(g, paint, 24, y - 12, txt, {anchor: 'start', size: 12, bold: true, color: 'accent', halo: true, max: width - 48});
  };
  AP2.blocks.seq = (cfg) => {
    const width = cfg.w || 720;
    const height = TOP + cfg.steps.length * GAP + 10;
    const root = svg('svg', {viewBox: '0 0 ' + width + ' ' + height, role: 'img', 'aria-label': cfg.cap || 'Sequenzdiagramm'});
    st(root, {width: '100%', height: 'auto', display: 'block', fontFamily: S.font.sans});
    const paint = AP2.paint(root);
    const span = cfg.actors.length > 1 ? (width - 160) / (cfg.actors.length - 1) : 0;
    const xs = cfg.actors.map((name, idx) => 80 + idx * span);
    xs.forEach((x, idx) => {
      root.appendChild(paint(svg('line', {x1: x, x2: x, y1: 48, y2: height - 4}), {s: 'line', sw: 1, dash: '5 5'}));
      header(root, paint, x, cfg.actors[idx], cfg.actors.length > 1 ? Math.min(span - 10, 2 * x - 8, 2 * (width - x) - 8) : width - 16);
    });
    cfg.steps.forEach((step, i) => {
      const y = TOP + i * GAP;
      if (step[0] === 'note') return note(root, paint, xs[idxOf(cfg, step[1])], y, step[2], width);
      if (step[0] === 'sep') return sep(root, paint, width, y, step[1]);
      const from = xs[idxOf(cfg, step[0])];
      const to = xs[idxOf(cfg, step[1])];
      if (from === to) return selfCall(root, paint, from, y, step[2], width - from - 46);
      arrow(root, paint, from, to, y, step[3]);
      return AP2.shapes.text(root, paint, (from + to) / 2, y - 12, step[2], {size: 12, color: 'text2', halo: true, max: Math.abs(to - from) - 12});
    });
    const box = h('div', {style: {border: '1px solid', borderRadius: S.r.md, padding: S.sp[3], margin: '0 0 ' + S.sp[5]}}, [root]);
    if (cfg.cap) box.appendChild(AP2.tint(h('div', {text: cfg.cap, style: {fontSize: S.f.sm, textAlign: 'center', marginTop: S.sp[2]}}), 'text2'));
    return AP2.theme.bind(box, (n, c) => { n.style.backgroundColor = c.surface; n.style.borderColor = c.border; });
  };
})();
;
// viz/chart.js
// Balken- und Liniendiagramme mit Achsen, Gitternetz und Legende.
(function () {
  const {h, svg, st} = AP2;
  const S = AP2.S;
  const COLORS = ['accent', 'text', 'text3', 'ok', 'bad'];
  const M = {l: 58, r: 20, t: 38, b: 44};
  const niceMax = (val) => {
    const pow = Math.pow(10, Math.floor(Math.log10(val || 1)));
    const step = [1, 2, 2.5, 5, 10].find((s) => s * pow >= val / 1) || 10;
    return step * pow;
  };
  const grid = (g, paint, cfg, plot, ymax) => {
    // ymin (nur Liniendiagramme): negative Werte, zum Beispiel kumulierte Zahlungen bei der Amortisation; die Nulllinie wird betont.
    const ymin = cfg.ymin || 0;
    for (let i = 0; i <= 4; i++) {
      const y = M.t + plot.h - (plot.h * i) / 4;
      const val = ymin + ((ymax - ymin) * i) / 4;
      g.appendChild(paint(svg('line', {x1: M.l, x2: M.l + plot.w, y1: y, y2: y}), {s: val === 0 && ymin < 0 ? 'text3' : 'border', sw: val === 0 && ymin < 0 ? 1.5 : 1}));
      AP2.shapes.text(g, paint, M.l - 8, y, String(Math.round(val * 100) / 100), {anchor: 'end', size: 11, color: 'text3'});
    }
    if (cfg.yl) AP2.shapes.text(g, paint, M.l, 16, cfg.yl, {anchor: 'start', size: 12, color: 'text2'});
  };
  const bars = (g, paint, cfg, plot, ymax) => {
    const groupW = plot.w / cfg.labels.length;
    const barW = (groupW * 0.62) / cfg.series.length;
    cfg.labels.forEach((label, i) => {
      AP2.shapes.text(g, paint, M.l + groupW * (i + 0.5), M.t + plot.h + 18, String(label), {size: 12, color: 'text2', max: groupW - 6});
      cfg.series.forEach((s, j) => {
        const bh = (Math.min(s.d[i], ymax) / ymax) * plot.h;
        const x = M.l + groupW * i + groupW * 0.19 + barW * j;
        g.appendChild(paint(svg('rect', {x, y: M.t + plot.h - bh, width: barW - 3, height: bh, rx: 3}), {f: s.k || COLORS[j]}));
        if (cfg.vals) AP2.shapes.text(g, paint, x + (barW - 3) / 2, M.t + plot.h - bh - 9, String(s.d[i]), {size: 11, color: 'text2', max: barW + 2});
      });
    });
  };
  const lines = (g, paint, cfg, plot, ymax) => {
    const xs = cfg.labels.map((l, i) => M.l + (plot.w * i) / (cfg.labels.length - 1));
    cfg.labels.forEach((label, i) => AP2.shapes.text(g, paint, xs[i], M.t + plot.h + 18, String(label), {size: 12, color: 'text2', max: plot.w / (cfg.labels.length - 1) - 6}));
    cfg.series.forEach((s, j) => {
      // null = noch kein Wert (zum Beispiel Ist-Linie im Burndown bis heute).
      const pts = s.d.map((v, i) => (v === null ? null : xs[i].toFixed(1) + ',' + (M.t + plot.h - ((Math.max(Math.min(v, ymax), cfg.ymin || 0) - (cfg.ymin || 0)) / (ymax - (cfg.ymin || 0))) * plot.h).toFixed(1))).filter(Boolean);
      g.appendChild(paint(svg('polyline', {points: pts.join(' ')}), {s: s.k || COLORS[j], sw: 2.5, dash: s.dash}));
    });
  };
  const legend = (g, paint, cfg, width) => {
    let x = width - M.r;
    cfg.series.slice().reverse().forEach((s, ri) => {
      const j = cfg.series.length - 1 - ri;
      const txt = AP2.shapes.text(g, paint, x, 16, s.n, {anchor: 'end', size: 12, color: 'text2'});
      x -= AP2.shapes.width(s.n, 12) + 14;
      g.appendChild(paint(svg('rect', {x: x + 1, y: 11, width: 11, height: 11, rx: 2}), {f: s.k || COLORS[j]}));
      x -= 12;
      return txt;
    });
  };
  AP2.blocks.chart = (cfg) => {
    const width = cfg.w || 720;
    const height = cfg.h || 340;
    const plot = {w: width - M.l - M.r, h: height - M.t - M.b};
    const root = svg('svg', {viewBox: '0 0 ' + width + ' ' + height, role: 'img', 'aria-label': cfg.cap || 'Diagramm'});
    st(root, {width: '100%', height: 'auto', display: 'block', fontFamily: S.font.sans});
    const paint = AP2.paint(root);
    const ymax = cfg.ymax || niceMax(Math.max(...[].concat(...cfg.series.map((s) => s.d))));
    grid(root, paint, cfg, plot, ymax);
    (cfg.kind === 'line' ? lines : bars)(root, paint, cfg, plot, ymax);
    if (cfg.series.length > 1 || cfg.legend) legend(root, paint, cfg, width);
    const box = h('div', {style: {border: '1px solid', borderRadius: S.r.md, padding: S.sp[3], margin: '0 0 ' + S.sp[5]}}, [root]);
    if (cfg.cap) box.appendChild(AP2.tint(h('div', {text: cfg.cap, style: {fontSize: S.f.sm, textAlign: 'center', marginTop: S.sp[2]}}), 'text2'));
    return AP2.theme.bind(box, (n, c) => { n.style.backgroundColor = c.surface; n.style.borderColor = c.border; });
  };
})();
;
