// viz/signs.js
// Sicherheitszeichen nach ASR A1.3 / DIN EN ISO 7010: Form und Farbe sind genormt, deshalb feste Farben statt Theme.
(function () {
  const {h, svg, st} = AP2;
  const S = AP2.S;
  const RED = '#d32f2f';
  const BLUE = '#1565c0';
  const YELLOW = '#f9c80e';
  const GREEN = '#2e7d32';
  const WHITE = '#ffffff';
  const BLACK = '#1a1a1a';
  const el = (tag, attrs) => svg(tag, attrs);
  // Symbole in der Mitte (vereinfacht): Ausrufezeichen, Pfeil, Kreuz, Flamme, Person.
  const glyph = (kind, color) => {
    if (kind === 'excl') return [el('rect', {x: 46, y: 26, width: 8, height: 30, rx: 3, fill: color}), el('circle', {cx: 50, cy: 66, r: 5, fill: color})];
    if (kind === 'arrow') return [el('path', {d: 'M28 50h36M52 36l16 14l-16 14', stroke: color, 'stroke-width': 9, fill: 'none', 'stroke-linecap': 'round', 'stroke-linejoin': 'round'})];
    if (kind === 'cross') return [el('path', {d: 'M42 26h16v16h16v16H58v16H42V58H26V42h16z', fill: color})];
    if (kind === 'flame') return [el('path', {d: 'M50 22c6 12 18 18 18 34a18 18 0 0 1-36 0c0-8 4-13 8-16c0 6 3 9 6 10c-2-10 0-20 4-28z', fill: color})];
    if (kind === 'bolt') return [el('path', {d: 'M54 24L36 54h12l-6 22l20-32H50z', fill: color})];
    if (kind === 'phone') return [el('rect', {x: 40, y: 26, width: 20, height: 40, rx: 4, fill: color})];
    if (kind === 'person') return [el('circle', {cx: 50, cy: 32, r: 7, fill: color}), el('path', {d: 'M50 42v18M38 50h24M50 60l-9 14M50 60l9 14', stroke: color, 'stroke-width': 6, 'stroke-linecap': 'round', fill: 'none'})];
    return [];
  };
  const SHAPE = {
    verbot: (g) => [el('circle', {cx: 50, cy: 50, r: 40, fill: WHITE, stroke: RED, 'stroke-width': 10})].concat(glyph(g, BLACK), [el('line', {x1: 22, y1: 22, x2: 78, y2: 78, stroke: RED, 'stroke-width': 9})]),
    gebot: (g) => [el('circle', {cx: 50, cy: 50, r: 44, fill: BLUE})].concat(glyph(g, WHITE)),
    warn: (g) => [el('path', {d: 'M50 8L94 86H6z', fill: YELLOW, stroke: BLACK, 'stroke-width': 5, 'stroke-linejoin': 'round'})].concat(glyph(g, BLACK).map((n) => { n.setAttribute('transform', 'translate(0 8) scale(1)'); return n; })),
    rettung: (g) => [el('rect', {x: 6, y: 6, width: 88, height: 88, rx: 6, fill: GREEN})].concat(glyph(g, WHITE)),
    brand: (g) => [el('rect', {x: 6, y: 6, width: 88, height: 88, rx: 6, fill: RED})].concat(glyph(g, WHITE)),
  };
  // items: [art, Symbol, Titel, Beschreibung]
  AP2.blocks.signs = (items, cap) => {
    const cards = items.map(([kind, g, title, desc]) => {
      const pic = svg('svg', {viewBox: '0 0 100 100', width: 72, height: 72, role: 'img', 'aria-label': title}, SHAPE[kind](g));
      st(pic, {display: 'block', flexShrink: 0});
      const t = AP2.tint(h('div', {text: title, style: {fontWeight: S.fw.bold, fontSize: S.f.sm}}), 'text');
      const d = AP2.tint(h('div', {text: desc, style: {fontSize: S.f.xs, lineHeight: '1.45', marginTop: '2px'}}), 'text2');
      const card = h('div', {style: {flex: '1 1 220px', display: 'flex', gap: S.sp[3], alignItems: 'center', padding: '10px 12px', borderRadius: S.r.md, border: '1px solid'}}, [pic, h('div', {}, [t, d])]);
      return AP2.theme.bind(card, (n, c) => { n.style.backgroundColor = c.surface; n.style.borderColor = c.border; });
    });
    const box = h('div', {style: {margin: '0 0 ' + S.sp[5]}}, [h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[2]}}, cards)]);
    if (cap) box.appendChild(AP2.tint(h('div', {text: cap, style: {fontSize: S.f.sm, textAlign: 'center', marginTop: S.sp[2]}}), 'text2'));
    return box;
  };
})();
;
// tools/kit.js
// Bausteine für interaktive Werkzeuge: Eingabefelder, Auswahl, Ergebnisfläche.
(function () {
  const {h, st, on} = AP2;
  const S = AP2.S;
  const col = (kids) => h('div', {style: {display: 'flex', flexDirection: 'column', gap: S.sp[4]}}, kids);
  const row = (kids) => h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[3], alignItems: 'flex-end'}}, kids);
  const labeled = (text, control) => {
    const lab = AP2.tint(h('div', {text, style: {fontSize: S.f.xs, fontWeight: S.fw.med, marginBottom: '4px'}}), 'text2');
    return h('div', {style: {flex: '1 1 150px'}}, [lab, control]);
  };
  const input = (text, value, fn, type) => {
    const el = AP2.field(h('input', {attrs: {type: type || 'text', value: String(value), 'aria-label': text}, style: {width: '100%'}}));
    on(el, 'input', () => fn(el.value));
    return {el: labeled(text, el), input: el, get: () => el.value, set: (v) => { el.value = v; }};
  };
  const select = (text, opts, fn) => {
    const el = AP2.field(h('select', {attrs: {'aria-label': text}, style: {width: '100%'}},
      opts.map(([val, name]) => h('option', {text: name, attrs: {value: val}}))));
    on(el, 'change', () => fn(el.value));
    return {el: labeled(text, el), input: el, get: () => el.value};
  };
  // Ergebnisfläche: show([[Name, Wert], ...]) füllt Zeilen neu.
  const result = () => {
    const box = h('div', {style: {padding: S.sp[4], borderRadius: S.r.md, border: '1px solid', display: 'flex', flexDirection: 'column', gap: S.sp[2]}});
    AP2.theme.bind(box, (n, c) => st(n, {backgroundColor: c.surface2, borderColor: c.border}));
    box.show = (rows) => {
      AP2.dispose(box);
      while (box.firstChild) box.removeChild(box.firstChild);
      rows.forEach(([name, val, mono]) => {
        const key = AP2.tint(h('div', {text: name, style: {flex: '0 0 130px', fontSize: S.f.sm}}), 'text2');
        const value = AP2.tint(h('div', {text: String(val), style: {flex: '1 1 150px', fontWeight: S.fw.med, fontFamily: mono ? S.font.mono : S.font.sans, wordBreak: 'break-all'}}), 'text');
        box.appendChild(h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[3]}}, [key, value]));
      });
    };
    return box;
  };
  const note = (text) => AP2.tint(h('div', {text, style: {fontSize: S.f.sm}}), 'text2');
  AP2.tk = {col, row, labeled, input, select, result, note};
})();
;
// tools/bin.js
// Werkzeug: Zahlen und IPv4-Adressen in Binär, Hex und Dezimal umrechnen.
(function () {
  const {tk} = AP2;
  const pad = (txt, len) => txt.padStart(len, '0');
  const groups = (txt) => txt.match(/.{1,4}/g).join(' ');
  AP2.tools.bin = () => {
    const out = tk.result();
    const dec = tk.input('Dezimalzahl (0 bis 4294967295)', 202, (v) => update(), 'number');
    const ip = tk.input('IPv4-Adresse', '192.168.10.77', () => update());
    const update = () => {
      const n = Math.max(0, Math.min(4294967295, Math.floor(Number(dec.get()) || 0)));
      const bits = pad(n.toString(2), n > 255 ? 32 : 8);
      const rows = [['Binär', groups(bits), true], ['Hexadezimal', n.toString(16).toUpperCase(), true], ['Oktal', n.toString(8), true]];
      const parts = ip.get().split('.').map(Number);
      const ok = parts.length === 4 && parts.every((x) => Number.isInteger(x) && x >= 0 && x <= 255);
      rows.push(['IPv4 binär', ok ? parts.map((x) => pad(x.toString(2), 8)).join('.') : 'ungültige Adresse', true]);
      if (ok) rows.push(['IPv4 als Zahl', parts.reduce((a, x) => a * 256 + x, 0)]);
      out.show(rows);
    };
    update();
    return tk.col([tk.note('Jede Stelle im Binärsystem ist eine Zweierpotenz: 128, 64, 32, 16, 8, 4, 2, 1.'), tk.row([dec.el, ip.el]), out]);
  };
})();
;
// tools/subnet.js
// Werkzeug: Subnetting-Rechner mit farbiger Binärdarstellung (Netzteil und Hostteil).
(function () {
  const {h} = AP2;
  const {tk} = AP2;
  const toInt = (txt) => {
    const p = txt.trim().split('.').map(Number);
    return p.length === 4 && p.every((x) => Number.isInteger(x) && x >= 0 && x <= 255) ? ((p[0] * 256 + p[1]) * 256 + p[2]) * 256 + p[3] : null;
  };
  const toIp = (n) => [24, 16, 8, 0].map((s) => Math.floor(n / 2 ** s) % 256).join('.');
  const maskOf = (pre) => (pre === 0 ? 0 : (0xFFFFFFFF << (32 - pre)) >>> 0);
  const binView = (n, pre) => {
    const bits = (n >>> 0).toString(2).padStart(32, '0');
    const wrap = h('div', {style: {fontFamily: AP2.S.font.mono, fontSize: AP2.S.f.md, display: 'flex', flexWrap: 'wrap', gap: '4px'}});
    for (let i = 0; i < 4; i++) {
      const oct = h('span', {}, bits.slice(i * 8, i * 8 + 8).split('').map((bit, j) => {
        const net = i * 8 + j < pre;
        const el = h('span', {text: bit, style: {fontWeight: net ? '700' : '400'}});
        return AP2.tint(el, net ? 'accent' : 'text2');
      }));
      wrap.appendChild(oct);
      if (i < 3) wrap.appendChild(AP2.tint(h('span', {text: '.'}), 'text3'));
    }
    return wrap;
  };
  AP2.tools.subnet = () => {
    const out = tk.result();
    const view = h('div');
    const ip = tk.input('IP-Adresse', '192.168.10.77', () => update());
    const pre = tk.input('Präfix (CIDR, 0 bis 32)', 26, () => update(), 'number');
    const update = () => {
      const addr = toInt(ip.get());
      const p = Math.floor(Number(pre.get()));
      while (view.firstChild) view.removeChild(view.firstChild);
      if (addr === null || !(p >= 0 && p <= 32)) return out.show([['Fehler', 'Bitte gültige Adresse und Präfix eingeben']]);
      const mask = maskOf(p);
      const net = (addr & mask) >>> 0;
      const bc = (net | (~mask >>> 0)) >>> 0;
      const hosts = p >= 31 ? (p === 31 ? 2 : 1) : 2 ** (32 - p) - 2;
      out.show([['Subnetzmaske', toIp(mask), true], ['Wildcard', toIp(~mask >>> 0), true], ['Netzadresse', toIp(net), true], ['Broadcast', toIp(bc), true],
        ['Erster Host', p >= 31 ? '-' : toIp(net + 1), true], ['Letzter Host', p >= 31 ? '-' : toIp(bc - 1), true], ['Nutzbare Hosts', hosts]]);
      view.appendChild(tk.note('Adresse binär (fett und farbig = Netzanteil, grau = Hostanteil):'));
      view.appendChild(binView(addr, p));
      view.appendChild(binView(mask, p));
    };
    update();
    return tk.col([tk.row([ip.el, pre.el]), out, view]);
  };
})();
