// tools/search.js
// Werkzeug: Lineare und binäre Suche im Vergleich, Schritt für Schritt.
(function () {
  const {tk} = AP2;
  const DATA = [3, 8, 12, 17, 21, 26, 31, 38, 42, 47, 53, 59, 64, 70, 77, 85];
  const binary = (target) => {
    const steps = [];
    let lo = 0;
    let hi = DATA.length - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      const rel = DATA[mid] === target ? 'gefunden' : DATA[mid] < target ? 'zu klein, rechts weiter' : 'zu groß, links weiter';
      steps.push(['Schritt ' + (steps.length + 1), 'Bereich [' + lo + '..' + hi + '], Mitte ' + mid + ' = ' + DATA[mid] + ': ' + rel]);
      if (DATA[mid] === target) return {steps, found: mid};
      if (DATA[mid] < target) lo = mid + 1; else hi = mid - 1;
    }
    return {steps, found: -1};
  };
  AP2.tools.search = () => {
    const out = tk.result();
    const val = tk.input('Gesuchte Zahl', 53, () => update(), 'number');
    const update = () => {
      const target = Number(val.get());
      const lin = DATA.indexOf(target);
      const bin = binary(target);
      out.show([['Sortierte Daten', DATA.join(', '), true], ['Lineare Suche', (lin < 0 ? DATA.length : lin + 1) + ' Vergleiche, ' + (lin < 0 ? 'nicht gefunden' : 'Index ' + lin)]]
        .concat(bin.steps, [['Binäre Suche', bin.steps.length + ' Vergleiche, ' + (bin.found < 0 ? 'nicht gefunden' : 'Index ' + bin.found)]]));
    };
    update();
    return tk.col([tk.note('Binäre Suche braucht sortierte Daten und halbiert den Suchbereich: O(log n) statt O(n).'), val.el, out]);
  };
})();
;
// tools/sortalgo.js
// Sortieralgorithmen als Einzelschritte: jede Funktion meldet (Feld, markierte Indizes).
(function () {
  const bubble = (a, rec) => {
    for (let i = 0; i < a.length - 1; i++) {
      for (let j = 0; j < a.length - 1 - i; j++) {
        rec(a, [j, j + 1]);
        if (a[j] > a[j + 1]) { [a[j], a[j + 1]] = [a[j + 1], a[j]]; rec(a, [j, j + 1]); }
      }
    }
  };
  const selection = (a, rec) => {
    for (let i = 0; i < a.length - 1; i++) {
      let min = i;
      for (let j = i + 1; j < a.length; j++) { rec(a, [min, j]); if (a[j] < a[min]) min = j; }
      if (min !== i) { [a[i], a[min]] = [a[min], a[i]]; rec(a, [i, min]); }
    }
  };
  const insertion = (a, rec) => {
    for (let i = 1; i < a.length; i++) {
      let j = i;
      while (j > 0) {
        rec(a, [j - 1, j]);
        if (a[j - 1] <= a[j]) break;
        [a[j - 1], a[j]] = [a[j], a[j - 1]];
        rec(a, [j - 1, j]);
        j--;
      }
    }
  };
  const quick = (a, rec) => {
    const part = (lo, hi) => {
      const pivot = a[hi];
      let i = lo;
      for (let j = lo; j < hi; j++) {
        rec(a, [j, hi]);
        if (a[j] < pivot) { [a[i], a[j]] = [a[j], a[i]]; rec(a, [i, j]); i++; }
      }
      [a[i], a[hi]] = [a[hi], a[i]];
      rec(a, [i, hi]);
      return i;
    };
    const run = (lo, hi) => { if (lo < hi) { const p = part(lo, hi); run(lo, p - 1); run(p + 1, hi); } };
    run(0, a.length - 1);
  };
  AP2.sortAlgos = {
    bubble: ['Bubble Sort, O(n^2)', bubble], selection: ['Selection Sort, O(n^2)', selection],
    insertion: ['Insertion Sort, O(n^2)', insertion], quick: ['Quick Sort, O(n log n) im Mittel', quick],
  };
})();
;
// tools/sort.js
// Werkzeug: animierter Sortier-Visualisierer mit Vergleichszähler.
(function () {
  const {h, st} = AP2;
  const {tk} = AP2;
  const COUNT = 24;
  const TICK = 60;
  const BAR_AREA = 160;
  const shuffle = () => Array.from({length: COUNT}, (_, i) => i + 1).sort(() => Math.random() - 0.5);
  const frames = (key, data) => {
    const list = [];
    AP2.sortAlgos[key][1](data.slice(), (arr, hi) => list.push({arr: arr.slice(), hi}));
    return list;
  };
  AP2.tools.sort = () => {
    let data = shuffle();
    let list = [];
    let pos = 0;
    let timer = null;
    const stage = h('div', {style: {display: 'flex', alignItems: 'flex-end', gap: '3px', height: BAR_AREA + 'px'}});
    const info = tk.note('');
    const algo = tk.select('Algorithmus', Object.keys(AP2.sortAlgos).map((k) => [k, AP2.sortAlgos[k][0]]), () => reset());
    const draw = (arr, hi) => {
      while (stage.firstChild) stage.removeChild(stage.firstChild);
      arr.forEach((v, i) => {
        const bar = h('div', {style: {flex: '1 1 0', height: (v / COUNT) * BAR_AREA + 'px', borderRadius: '3px 3px 0 0'}});
        AP2.theme.bind(bar, (n, c) => { n.style.backgroundColor = hi && hi.includes(i) ? c.accent : c.border; });
        stage.appendChild(bar);
      });
      info.textContent = 'Schritte: ' + pos + ' von ' + list.length;
    };
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
    const step = () => {
      if (!stage.isConnected || pos >= list.length) return stop();
      draw(list[pos].arr, list[pos].hi);
      pos++;
    };
    const reset = () => { stop(); pos = 0; list = frames(algo.get(), data); draw(data, null); };
    const mix = () => { data = shuffle(); reset(); };
    const play = () => { if (!timer) { if (pos >= list.length) reset(); timer = setInterval(step, TICK); } };
    reset();
    const bar = tk.row([AP2.btn({text: 'Start', kind: 'primary', fn: play}), AP2.btn({text: 'Pause', fn: stop}), AP2.btn({text: 'Ein Schritt', fn: step}), AP2.btn({text: 'Mischen', fn: mix})]);
    st(bar, {alignItems: 'center'});
    return tk.col([tk.row([algo.el]), bar, stage, info, tk.note('Hervorgehoben (Akzentfarbe) sind die gerade verglichenen oder getauschten Elemente.')]);
  };
})();
;
// tools/kuendigung.js
// Werkzeug: Kündigungsfrist und frühestes Vertragsende berechnen (§ 622 BGB).
(function () {
  const {tk} = AP2;
  const DAY = 86400000;
  const MONTHS = [[20, 7], [15, 6], [12, 5], [10, 4], [8, 3], [5, 2], [2, 1]];
  const fmt = (d) => d.toLocaleDateString('de-DE', {day: '2-digit', month: '2-digit', year: 'numeric'});
  const addMonths = (d, n) => {
    const last = new Date(d.getFullYear(), d.getMonth() + n + 1, 0).getDate();
    return new Date(d.getFullYear(), d.getMonth() + n, Math.min(d.getDate(), last));
  };
  const monthEnd = (d) => new Date(d.getFullYear(), d.getMonth() + 1, 0);
  const next15orEnd = (d) => (d.getDate() <= 15 ? new Date(d.getFullYear(), d.getMonth(), 15) : monthEnd(d));
  const rule = (who, years, probe) => {
    if (probe) return {text: '2 Wochen (Probezeit), jederzeit', end: (d) => new Date(d.getTime() + 14 * DAY)};
    const hit = who === 'ag' ? MONTHS.find((m) => years >= m[0]) : null;
    if (hit) return {text: hit[1] + ' Monat(e) zum Monatsende', end: (d) => monthEnd(addMonths(d, hit[1]))};
    return {text: '4 Wochen zum 15. oder zum Monatsende', end: (d) => next15orEnd(new Date(d.getTime() + 28 * DAY))};
  };
  AP2.tools.kuendigung = () => {
    const out = tk.result();
    const who = tk.select('Wer kündigt?', [['ag', 'Arbeitgeber'], ['an', 'Arbeitnehmer']], () => update());
    const years = tk.input('Betriebszugehörigkeit (Jahre)', 6, () => update(), 'number');
    const probe = tk.select('Probezeit?', [['0', 'Nein'], ['1', 'Ja (max. 6 Monate)']], () => update());
    const today = new Date().toISOString().slice(0, 10);
    const date = tk.input('Zugang der Kündigung', today, () => update(), 'date');
    const update = () => {
      const d = new Date(date.get() + 'T00:00:00');
      if (isNaN(d)) return out.show([['Hinweis', 'Bitte ein gültiges Datum wählen']]);
      const r = rule(who.get(), Number(years.get()), probe.get() === '1');
      out.show([['Kündigungsfrist', r.text], ['Zugang', fmt(d)], ['Frühestes Ende', fmt(r.end(d))]]);
    };
    update();
    return tk.col([tk.note('Die Verlängerung nach Betriebszugehörigkeit gilt nur für den Arbeitgeber. Tarifvertrag oder Arbeitsvertrag können abweichen. Keine Rechtsberatung.'), tk.row([who.el, years.el, probe.el, date.el]), out]);
  };
})();
;
// tools/urlaub.js
// Werkzeug: gesetzlicher Mindesturlaub und Teilurlaub (BUrlG).
(function () {
  const {tk} = AP2;
  const BASE = 24;
  const WEEK = 6;
  const FULL_UNTIL_MONTH = 7;
  AP2.tools.urlaub = () => {
    const out = tk.result();
    const days = tk.input('Arbeitstage pro Woche', 5, () => update(), 'number');
    const contract = tk.input('Urlaubstage laut Vertrag (Jahr)', 28, () => update(), 'number');
    const month = tk.select('Eintritt am 1. des Monats (im Jahr)', ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'].map((m, i) => [String(i + 1), m]), () => update());
    const update = () => {
      const d = Number(days.get());
      const c = Number(contract.get());
      if (!(d > 0 && d <= 6) || !(c >= 0)) return out.show([['Hinweis', 'Arbeitstage zwischen 1 und 6 eingeben']]);
      const legal = (BASE * d) / WEEK;
      const m = Number(month.get());
      const full = m <= FULL_UNTIL_MONTH;
      const part = full ? c : Math.ceil(((13 - m) / 12) * c - 0.5 + 1e-9);
      out.show([['Mindesturlaub', legal.toFixed(1) + ' Tage (24 mal ' + d + ' / 6)'], ['Vertragsurlaub', c + ' Tage'],
        ['Im Eintrittsjahr', part + ' Tage' + (full ? ' (Wartezeit im Jahr erfüllt, voller Anspruch)' : ' (Teilurlaub: 1/12 je vollem Monat)')]]);
    };
    update();
    return tk.col([tk.note('Wartezeit: 6 Monate. Wer in der ersten Jahreshälfte beginnt, erreicht sie im selben Jahr und hat vollen Anspruch.'), tk.row([days.el, contract.el, month.el]), out]);
  };
})();
;
// tools/kalk.js
// Werkzeuge für kaufmännische Rechnungen: Break-even, Bezugskalkulation, optimale Bestellmenge.
(function () {
  const {tk} = AP2;
  const eur = (v) => v.toLocaleString('de-DE', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' €';
  const num = (field) => Number(String(field.get()).replace(',', '.'));

  // Gewinnschwelle: Fixkosten / (Preis - variable Stückkosten).
  AP2.tools.breakeven = () => {
    const out = tk.result();
    const kf = tk.input('Fixkosten K_fix (€)', 10000, () => update(), 'number');
    const p = tk.input('Preis je Stück p (€)', 5, () => update(), 'number');
    const kv = tk.input('Variable Kosten je Stück k_v (€)', 2.5, () => update(), 'number');
    const x = tk.input('Absatzmenge x (Stück)', 6300, () => update(), 'number');
    const update = () => {
      const fix = num(kf); const price = num(p); const var1 = num(kv); const qty = num(x);
      const db = price - var1;
      if (!(db > 0)) return out.show([['Hinweis', 'Der Preis muss größer als die variablen Stückkosten sein, sonst gibt es keine Gewinnschwelle.']]);
      const be = fix / db;
      const gewinn = db * qty - fix;
      out.show([
        ['Deckungsbeitrag je Stück', eur(db) + '   (p - k_v)'],
        ['Gewinnschwelle (rechnerisch)', be.toLocaleString('de-DE', {maximumFractionDigits: 2}) + ' Stück'],
        ['Gewinnschwelle (ganze Stück)', Math.ceil(be) + ' Stück (immer aufrunden)'],
        ['Umsatz bei Gewinnschwelle', eur(be * price)],
        ['Gesamtkosten bei x', eur(fix + var1 * qty) + '   (K_fix + k_v · x)'],
        ['Erlös bei x', eur(price * qty) + '   (p · x)'],
        ['Ergebnis bei x', (gewinn >= 0 ? 'Gewinn ' : 'Verlust ') + eur(Math.abs(gewinn))],
      ]);
    };
    update();
    return tk.col([tk.note('Gewinnschwelle (Break-even-Menge) = Fixkosten / Deckungsbeitrag je Stück. Ab dieser Menge decken die Erlöse alle Kosten.'),
      tk.row([kf.el, p.el]), tk.row([kv.el, x.el]), out]);
  };

  // Bezugskalkulation (Einkauf): Listenpreis bis Bezugspreis.
  AP2.tools.bezug = () => {
    const out = tk.result();
    const lp = tk.input('Listenpreis je Stück (€ netto)', 1149, () => update(), 'number');
    const n = tk.input('Menge (Stück)', 10, () => update(), 'number');
    const ra = tk.input('Rabatt (%)', 5, () => update(), 'number');
    const sk = tk.input('Skonto (%)', 2, () => update(), 'number');
    const bk = tk.input('Bezugskosten gesamt (€)', 50, () => update(), 'number');
    const update = () => {
      const list = num(lp) * num(n);
      const rabatt = list * num(ra) / 100;
      const ziel = list - rabatt;
      const skonto = ziel * num(sk) / 100;
      const bar = ziel - skonto;
      const bezug = bar + num(bk);
      out.show([
        ['Listeneinkaufspreis', eur(list)], ['- Rabatt', eur(rabatt)], ['= Zieleinkaufspreis', eur(ziel)],
        ['- Skonto', eur(skonto)], ['= Bareinkaufspreis', eur(bar)], ['+ Bezugskosten', eur(num(bk))],
        ['= Bezugspreis (Einstandspreis)', eur(bezug)], ['Bezugspreis je Stück', eur(num(n) > 0 ? bezug / num(n) : 0)],
      ]);
    };
    update();
    return tk.col([tk.note('Reihenfolge merken: erst Rabatt (vom Listenpreis), dann Skonto (vom Zieleinkaufspreis), dann Bezugskosten addieren.'),
      tk.row([lp.el, n.el]), tk.row([ra.el, sk.el, bk.el]), out]);
  };

  // Optimale Bestellmenge (Andler-Formel) mit Kontrolltabelle.
  AP2.tools.andler = () => {
    const out = tk.result();
    const jb = tk.input('Jahresbedarf (Stück)', 1200, () => update(), 'number');
    const kb = tk.input('Kosten je Bestellung (€)', 25, () => update(), 'number');
    const ep = tk.input('Einstandspreis je Stück (€)', 19.5, () => update(), 'number');
    const ls = tk.input('Lagerkostensatz (%)', 20, () => update(), 'number');
    const update = () => {
      const m = num(jb); const fix = num(kb); const price = num(ep); const rate = num(ls) / 100;
      if (!(m > 0 && fix > 0 && price > 0 && rate > 0)) return out.show([['Hinweis', 'Alle Werte müssen größer als 0 sein.']]);
      const q = Math.sqrt((200 * m * fix) / (price * num(ls)));
      const cost = (x) => (m / x) * fix + (x / 2) * price * rate;
      out.show([
        ['Optimale Bestellmenge', q.toLocaleString('de-DE', {maximumFractionDigits: 1}) + ' Stück'],
        ['Bestellungen pro Jahr', (m / q).toLocaleString('de-DE', {maximumFractionDigits: 1})],
        ['Bestellkosten / Jahr', eur((m / q) * fix)], ['Lagerkosten / Jahr', eur((q / 2) * price * rate)],
        ['Gesamtkosten / Jahr', eur(cost(q))],
        ['Zum Vergleich: halbe Menge', eur(cost(q / 2)) + ' Gesamtkosten'], ['Zum Vergleich: doppelte Menge', eur(cost(q * 2)) + ' Gesamtkosten'],
      ]);
    };
    update();
    return tk.col([tk.note('Andler-Formel: x_opt = √(200 · Jahresbedarf · Bestellkosten / (Einstandspreis · Lagerkostensatz in %)). Im Optimum sind Bestell- und Lagerkosten gleich hoch.'),
      tk.row([jb.el, kb.el]), tk.row([ep.el, ls.el]), out]);
  };
})();
;
// tools/calc.js
// Rechner zu neuen Themen: DPMO, Bestehensregeln, Energiekosten, Übertragungszeit, RSA, Blockchain, Neuron, Prüfziffern.
(function () {
  const {h, tk, on} = AP2;
  const S = AP2.S;
  const num = (v) => Number(String(v).replace(',', '.'));
  const de = (v, d) => Number(v).toLocaleString('de-DE', {minimumFractionDigits: d || 0, maximumFractionDigits: d === undefined ? 2 : d});
  const holder = () => h('div');
  const table = (box, head, rows, mark) => { AP2.dispose(box); box.appendChild(AP2.blocks.table(head, rows, {mark: mark || []})); };

  // Inverse der Standardnormalverteilung (Näherung nach Acklam) für das Sigma-Niveau.
  const invNorm = (p) => {
    const a = [-39.6968302866538, 220.946098424521, -275.928510446969, 138.357751867269, -30.6647980661472, 2.50662827745924];
    const b = [-54.4760987982241, 161.585836858041, -155.698979859887, 66.8013118877197, -13.2806815528857];
    const c = [-0.00778489400243029, -0.322396458041136, -2.40075827716184, -2.54973253934373, 4.37466414146497, 2.93816398269878];
    const d = [0.00778469570904146, 0.32246712907004, 2.445134137143, 3.75440866190742];
    const lo = 0.02425;
    if (p < lo) { const q = Math.sqrt(-2 * Math.log(p)); return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
    if (p > 1 - lo) { const q = Math.sqrt(-2 * Math.log(1 - p)); return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
    const q = p - 0.5; const r = q * q;
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
  };
  AP2.tools.dpmo = () => {
    const out = tk.result();
    const f = tk.input('Gefundene Fehler', 17, () => update(), 'number');
    const u = tk.input('Geprüfte Einheiten', 5000, () => update(), 'number');
    const o = tk.input('Fehlermöglichkeiten je Einheit', 4, () => update(), 'number');
    const update = () => {
      const F = num(f.get()); const U = num(u.get()); const O = num(o.get());
      if (!(U > 0 && O > 0 && F >= 0)) return out.show([['Hinweis', 'Einheiten und Möglichkeiten müssen größer als 0 sein']]);
      const dpmo = F / (U * O) * 1e6;
      const yieldPct = 100 - dpmo / 1e4;
      const sigma = dpmo <= 0 ? 'über 6' : de(invNorm(1 - dpmo / 1e6) + 1.5, 2);
      out.show([['DPMO', de(dpmo, 1) + '  (= ' + F + ' / (' + U + ' mal ' + O + ') mal 1.000.000)'], ['Fehlerfrei (Ausbeute)', de(yieldPct, 5) + ' %'], ['Sigma-Niveau', sigma + ' (Kurzzeit, mit 1,5-Sigma-Verschiebung)'], ['Six Sigma erreicht?', dpmo <= 3.4 ? 'Ja (höchstens 3,4 DPMO)' : 'Nein (Ziel: höchstens 3,4 DPMO)']]);
    };
    update();
    return tk.col([tk.note('DPMO = Fehler / (Einheiten mal Möglichkeiten je Einheit) mal 1.000.000. Six Sigma heißt höchstens 3,4 DPMO.'), tk.row([f.el, u.el, o.el]), out]);
  };

  // Bestehensregeln der gestreckten Abschlussprüfung und mündliche Ergänzungsprüfung.
  const grade = (p) => AP2.exam.grade(p);
  AP2.tools.noten = () => {
    const out = holder();
    const extra = tk.result();
    const fields = [['t1', 'Teil 1 (AP1), Punkte', 70], ['doku', 'Projekt: Dokumentation', 75], ['praes', 'Projekt: Präsentation und Fachgespräch', 80], ['ps', 'Planen eines Softwareproduktes', 55], ['eua', 'Entwicklung und Umsetzung von Algorithmen', 45], ['wiso', 'Wirtschafts- und Sozialkunde', 60]]
      .map(([id, text, val]) => [id, tk.input(text, val, () => update(), 'number')]);
    const get = (id) => Math.max(0, Math.min(100, num(fields.find((f) => f[0] === id)[1].get()) || 0));
    const evaluate = (v) => {
      const proj = (v.doku + v.praes) / 2;
      const t2 = 0.5 * proj + 0.1 * v.ps + 0.1 * v.eua + 0.1 * v.wiso;
      const total = 0.2 * v.t1 + t2;
      const areas = [proj, v.ps, v.eua, v.wiso];
      const rules = [
        ['Gesamtergebnis Teil 1 + Teil 2 mindestens 50', total >= 50, de(total, 1) + ' Punkte'],
        ['Ergebnis Teil 2 mindestens ausreichend (50 %)', t2 >= 40, de(t2, 1) + ' von 80 = ' + de(t2 / 0.8, 1) + ' %'],
        ['Mindestens 3 Prüfungsbereiche von Teil 2 mit mindestens 50', areas.filter((a) => a >= 50).length >= 3, areas.filter((a) => a >= 50).length + ' von 4'],
        ['Kein Prüfungsbereich von Teil 2 ungenügend (unter 30)', areas.every((a) => a >= 30), areas.every((a) => a >= 30) ? 'erfüllt' : 'verletzt'],
      ];
      return {proj, t2, total, rules, ok: rules.every((r) => r[1])};
    };
    const update = () => {
      const v = {};
      fields.forEach(([id]) => { v[id] = get(id); });
      const r = evaluate(v);
      const g = grade(r.total);
      AP2.dispose(out);
      out.appendChild(AP2.blocks.table(['Regel', 'Erfüllt?', 'Wert'], r.rules.map(([t, ok, val]) => [t, ok ? '**ja**' : '**nein**', val])));
      out.appendChild(AP2.blocks[r.ok ? 'tip' : 'warn']((r.ok ? 'Bestanden mit ' : 'Nicht bestanden. Rechnerisch: ') + de(r.total, 1) + ' Punkten, Note ' + g[1] + ' (' + g[2] + '). Projekt: ' + de(r.proj, 1) + ' Punkte.'));
      // Ergänzungsprüfung: eine schriftliche Prüfung unter 50, neue Note = 2/3 schriftlich + 1/3 mündlich.
      const cand = ['ps', 'eua', 'wiso'].filter((id) => v[id] < 50);
      if (r.ok || !cand.length) { extra.show([['Ergänzungsprüfung', r.ok ? 'nicht nötig' : 'nicht möglich (keine schriftliche Prüfung unter 50 Punkten)']]); return; }
      const rows = cand.map((id) => {
        let need = null;
        for (let x = 0; x <= 100; x++) { const w = Object.assign({}, v, {[id]: (2 * v[id] + x) / 3}); if (evaluate(w).ok) { need = x; break; } }
        const name = fields.find((f) => f[0] === id)[1].el.textContent;
        return [name, need === null ? 'reicht nicht zum Bestehen' : 'mündlich mindestens ' + need + ' Punkte nötig'];
      });
      extra.show([['Ergänzungsprüfung', 'auf Antrag in genau einem Bereich: neues Ergebnis = 2/3 schriftlich + 1/3 mündlich']].concat(rows));
    };
    const grid = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[3]}}, fields.map((f) => f[1].el));
    update();
    return tk.col([tk.note('Gewichtung: Teil 1 20 %, Projekt 50 % (Dokumentation und Präsentation/Fachgespräch je zur Hälfte), PS 10 %, EUA 10 %, WiSo 10 %. Werte 0 bis 100 Punkte.'), grid, out, extra]);
  };

  AP2.tools.energie = () => {
    const out = tk.result();
    const n = tk.input('Anzahl Geräte', 16, () => update(), 'number');
    const w = tk.input('Leistung je Gerät (Watt)', 240, () => update(), 'number');
    const hrs = tk.input('Betriebsstunden pro Tag', 24, () => update(), 'number');
    const days = tk.input('Tage pro Jahr', 365, () => update(), 'number');
    const price = tk.input('Preis pro kWh (Euro)', '0,30', () => update());
    const update = () => {
      const kw = num(n.get()) * num(w.get()) / 1000;
      const kwh = kw * num(hrs.get()) * num(days.get());
      out.show([['Gesamtleistung', de(kw, 3) + ' kW'], ['Energie pro Jahr', de(kwh, 1) + ' kWh  (kW mal Stunden mal Tage)'], ['Kosten pro Jahr', de(kwh * num(price.get()), 2) + ' Euro'], ['Kosten pro Monat', de(kwh * num(price.get()) / 12, 2) + ' Euro']]);
    };
    update();
    return tk.col([tk.note('P in kW = Anzahl mal Watt / 1000. Energie W = P mal t. Kosten = kWh mal Preis.'), tk.row([n.el, w.el, hrs.el]), tk.row([days.el, price.el]), out]);
  };

  AP2.tools.transfer = () => {
    const out = tk.result();
    const size = tk.input('Datenmenge', 6, () => update(), 'number');
    const unit = tk.select('Einheit', [['1e9', 'GB (10^9 Byte)'], ['1e6', 'MB (10^6 Byte)'], ['1073741824', 'GiB (2^30 Byte)'], ['1e12', 'TB (10^12 Byte)']], () => update());
    const rate = tk.input('Datenrate', 420, () => update(), 'number');
    const runit = tk.select('Einheit der Rate', [['8e6', 'MByte/s'], ['1e6', 'Mbit/s'], ['1e9', 'Gbit/s']], () => update());
    const update = () => {
      const bits = num(size.get()) * num(unit.get()) * 8;
      const bps = num(rate.get()) * num(runit.get());
      if (!(bps > 0)) return out.show([['Hinweis', 'Datenrate muss größer als 0 sein']]);
      const sec = bits / bps;
      out.show([['Datenmenge', de(bits / 8e6, 0) + ' MB = ' + de(bits / 1e6, 0) + ' Mbit'], ['Zeit', de(sec, 2) + ' s' + (sec >= 60 ? ' = ' + de(sec / 60, 2) + ' min' : '') + (sec >= 3600 ? ' = ' + de(sec / 3600, 2) + ' h' : '')]]);
    };
    update();
    return tk.col([tk.note('Zeit = Datenmenge / Datenrate. Einheiten angleichen: 1 Byte = 8 Bit. Beispiel: 6 GB bei 420 MByte/s = 6.000 / 420 = 14,3 s.'), tk.row([size.el, unit.el]), tk.row([rate.el, runit.el]), out]);
  };

  // Spielzeug-RSA mit BigInt: Schlüssel aus p, q, e berechnen, Zahl ver- und entschlüsseln.
  const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));
  const modpow = (b, e, m) => { let r = 1n; b %= m; while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; } return r; };
  const inverse = (a, m) => { let [r0, r1, s0, s1] = [a, m, 1n, 0n]; while (r1) { const q = r0 / r1; [r0, r1] = [r1, r0 - q * r1]; [s0, s1] = [s1, s0 - q * s1]; } return r0 === 1n ? ((s0 % m) + m) % m : null; };
  const prime = (n) => { if (n < 2n) return false; for (let i = 2n; i * i <= n; i++) if (n % i === 0n) return false; return true; };
  AP2.tools.rsa = () => {
    const out = tk.result();
    const p = tk.input('Primzahl p', 11, () => update(), 'number');
    const q = tk.input('Primzahl q', 17, () => update(), 'number');
    const e = tk.input('Öffentlicher Exponent e', 7, () => update(), 'number');
    const m = tk.input('Klartext-Zahl X', 11, () => update(), 'number');
    const update = () => {
      try {
        const P = BigInt(p.get()); const Q = BigInt(q.get()); const E = BigInt(e.get()); const X = BigInt(m.get());
        if (!prime(P) || !prime(Q) || P === Q) return out.show([['Hinweis', 'p und q müssen verschiedene Primzahlen sein']]);
        const N = P * Q; const phi = (P - 1n) * (Q - 1n);
        if (gcd(E, phi) !== 1n) return out.show([['Hinweis', 'e muss teilerfremd zu phi(N) = ' + phi + ' sein']]);
        if (X >= N) return out.show([['Hinweis', 'X muss kleiner als N = ' + N + ' sein']]);
        const D = inverse(E, phi); const V = modpow(X, E, N);
        out.show([['N = p mal q', String(N), true], ['phi(N) = (p-1)(q-1)', String(phi), true], ['Privat d (e mal d mod phi = 1)', String(D), true], ['Öffentlicher Schlüssel', '(' + E + ', ' + N + ')', true], ['Privater Schlüssel', '(' + D + ', ' + N + ')', true],
          ['Verschlüsseln V = X^e mod N', X + '^' + E + ' mod ' + N + ' = ' + V, true], ['Entschlüsseln X = V^d mod N', V + '^' + D + ' mod ' + N + ' = ' + modpow(V, D, N), true]]);
      } catch (err) { out.show([['Hinweis', 'Bitte ganze Zahlen eingeben']]); }
    };
    update();
    return tk.col([tk.note('Rechenregel für die Hand: (a mal b) mod m = ((a mod m) mal (b mod m)) mod m. Große Potenzen in kleine zerlegen.'), tk.row([p.el, q.el, e.el, m.el]), out]);
  };

  // Blockchain im Kleinen: Hash = (Summe der ASCII-Werte ohne Leerzeichen + Hash des Vorgängers) mod 999.
  const toyHash = (text, prev) => ([...String(text)].filter((ch) => ch !== ' ').reduce((a, ch) => a + ch.charCodeAt(0), 0) + prev) % 999;
  AP2.tools.blockchain = () => {
    const start = ['A zahlt 12 an B', 'C zahlt 5 an A', 'B zahlt 45 an X'];
    let prev = 0;
    const stored = start.map((t) => { prev = toyHash(t, prev); return prev; });
    const box = holder();
    const inputs = start.map((t, i) => {
      const el = AP2.field(h('input', {attrs: {type: 'text', value: t, 'aria-label': 'Daten Block ' + (i + 1)}, style: {width: '100%'}}));
      on(el, 'input', () => update());
      return el;
    });
    const cards = h('div', {style: {display: 'flex', flexWrap: 'wrap', gap: S.sp[3]}});
    const update = () => {
      AP2.dispose(cards);
      let p = 0;
      let broken = false;
      inputs.forEach((el, i) => {
        const now = toyHash(el.value, p);
        const bad = broken || now !== stored[i];
        if (bad) broken = true;
        const tone = bad ? 'bad' : 'ok';
        const card = h('div', {style: {flex: '1 1 200px', padding: '12px 14px', borderRadius: S.r.md, border: '2px solid'}}, [
          AP2.tint(h('div', {text: 'Block ' + (i + 1), style: {fontWeight: S.fw.bold, fontSize: S.f.sm, marginBottom: S.sp[2]}}), 'text'), el,
          AP2.tint(h('div', {text: 'Vorgänger-Hash: ' + p, style: {fontFamily: S.font.mono, fontSize: S.f.xs, marginTop: S.sp[2]}}), 'text2'),
          AP2.tint(h('div', {text: 'gespeichert: ' + stored[i] + '   neu berechnet: ' + now, style: {fontFamily: S.font.mono, fontSize: S.f.xs}}), tone),
          AP2.tint(h('div', {text: bad ? 'Kette gebrochen' : 'gültig', style: {fontWeight: S.fw.bold, fontSize: S.f.xs, marginTop: '4px'}}), tone)]);
        AP2.theme.bind(card, (n, c) => { n.style.borderColor = c[tone]; n.style.backgroundColor = c[tone + 'Soft']; });
        cards.appendChild(card);
        p = now;
      });
    };
    update();
    box.appendChild(cards);
    return tk.col([tk.note('Ändere die Daten eines Blocks: Sein neu berechneter Hash passt nicht mehr zum gespeicherten, und weil jeder Block den Hash seines Vorgängers enthält, sind alle folgenden Blöcke ebenfalls ungültig. Hash hier: (Summe der ASCII-Werte ohne Leerzeichen + Vorgänger-Hash) mod 999.'), box]);
  };

  // Ein Mini-Netz mit Schwellenwert-Aktivierung: 3 Eingaben, 2 versteckte Neuronen, 1 Ausgabe.
  AP2.tools.neuron = () => {
    const out = tk.result();
    const i1 = tk.input('I1: Einkommen (Tsd. Euro)', 65, () => update(), 'number');
    const i2 = tk.input('I2: Berufsjahre', 17, () => update(), 'number');
    const i3 = tk.input('I3: zurückgezahlte Kredite', 4, () => update(), 'number');
    const update = () => {
      const a = num(i1.get()); const b = num(i2.get()); const c = num(i3.get());
      const n1 = 1 * a + 1 * b; const h1 = n1 >= 60 ? 1 : 0;
      const n2 = 2 * b + 5 * c; const h2 = n2 >= 40 ? 1 : 0;
      const o = 20 + 40 * h1 + 30 * h2;
      out.show([['H1 Netzeingabe', '1 mal ' + a + ' + 1 mal ' + b + ' = ' + n1 + '  (Schwelle 60) => H1 = ' + h1], ['H2 Netzeingabe', '2 mal ' + b + ' + 5 mal ' + c + ' = ' + n2 + '  (Schwelle 40) => H2 = ' + h2], ['Ausgabe O', '20 + 40 mal ' + h1 + ' + 30 mal ' + h2 + ' = ' + o + ' % Bonität']]);
    };
    update();
    return tk.col([tk.note('Gewichte: H1 = 1 mal I1 + 1 mal I2, H2 = 2 mal I2 + 5 mal I3, Aktivierung: 1 wenn Summe mindestens Schwelle, sonst 0. Ausgabe O = 20 + 40 mal H1 + 30 mal H2 (Bias 20).'), tk.row([i1.el, i2.el, i3.el]), out]);
  };

  // Prüfziffern: ISBN-13/EAN-13 (Gewichte 1 und 3), ISBN-10 (Gewichte 10 bis 2, modulo 11), Luhn.
  AP2.tools.pruefziffer = () => {
    const out = holder();
    const res = tk.result();
    const inp = tk.input('Nummer (ohne oder mit Bindestrichen)', '978-3-7585-3368-6', () => update());
    const kind = tk.select('Verfahren', [['13', 'ISBN-13 / EAN-13'], ['10', 'ISBN-10'], ['luhn', 'Luhn (Kreditkarte, IMEI)']], () => update());
    const update = () => {
      const raw = inp.get().toUpperCase().replace(/[^0-9X]/g, '');
      const k = kind.get();
      const body = raw.slice(0, -1).split('').map(Number);
      const given = raw.slice(-1);
      if (k === '13') {
        if (raw.length !== 13) { AP2.dispose(out); return res.show([['Hinweis', '13 Ziffern nötig, gefunden: ' + raw.length]]); }
        const w = body.map((d, i) => (i % 2 ? 3 : 1));
        const sum = body.reduce((a, d, i) => a + d * w[i], 0);
        const check = (10 - (sum % 10)) % 10;
        table(out, ['Stelle'].concat(body.map((d, i) => String(i + 1))), [['Ziffer'].concat(body.map(String)), ['Gewicht'].concat(w.map(String)), ['Produkt'].concat(body.map((d, i) => String(d * w[i])))]);
        res.show([['Summe', String(sum)], ['Prüfziffer', '(10 - ' + sum + ' mod 10) mod 10 = ' + check], ['Ergebnis', String(check) === given ? 'gültig' : 'ungültig (angegeben: ' + given + ')']]);
      } else if (k === '10') {
        if (raw.length !== 10) { AP2.dispose(out); return res.show([['Hinweis', '10 Zeichen nötig']]); }
        const sum = body.reduce((a, d, i) => a + d * (10 - i), 0);
        const c = (11 - (sum % 11)) % 11;
        const check = c === 10 ? 'X' : String(c);
        table(out, ['Stelle'].concat(body.map((d, i) => String(i + 1))), [['Ziffer'].concat(body.map(String)), ['Gewicht'].concat(body.map((d, i) => String(10 - i)))]);
        res.show([['Summe', String(sum)], ['Prüfziffer', '(11 - ' + sum + ' mod 11) mod 11 = ' + check], ['Ergebnis', check === given ? 'gültig' : 'ungültig (angegeben: ' + given + ')']]);
      } else {
        const digits = raw.split('').map(Number);
        const rev = digits.slice(0, -1).reverse().map((d, i) => { if (i % 2) return d; const x = d * 2; return x > 9 ? x - 9 : x; });
        const sum = rev.reduce((a, d) => a + d, 0);
        const check = (10 - (sum % 10)) % 10;
        AP2.dispose(out);
        res.show([['Verfahren', 'von rechts jede zweite Ziffer verdoppeln (über 9: minus 9), alles addieren'], ['Summe', String(sum)], ['Prüfziffer', String(check)], ['Ergebnis', String(check) === given ? 'gültig' : 'ungültig']]);
      }
    };
    update();
    return tk.col([tk.row([inp.el, kind.el]), out, res]);
  };
})();
;
// tools/netcalc.js
// Netzwerk-Rechner: Routing-Entscheidung (längstes Präfix), VLSM-Planung, IPv6-Subnetze.
(function () {
  const {h, tk, on} = AP2;
  const S = AP2.S;
  const ip2n = (s) => { const p = String(s).trim().split('.').map(Number); return p.length === 4 && p.every((x) => x >= 0 && x <= 255 && Number.isInteger(x)) ? ((p[0] << 24) >>> 0) + (p[1] << 16) + (p[2] << 8) + p[3] : null; };
  const n2ip = (n) => [n >>> 24, (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join('.');
  const mask = (len) => (len === 0 ? 0 : (0xffffffff << (32 - len)) >>> 0);
  const area = (rows, value) => {
    const el = AP2.field(h('textarea', {attrs: {rows, spellcheck: 'false', 'aria-label': 'Eingabe'}, style: {width: '100%', fontFamily: S.font.mono, fontSize: S.f.sm, resize: 'vertical'}}));
    el.value = value;
    return el;
  };
  const box = () => h('div');

  // Routing-Tabelle: Zeilen "Ziel/Präfix Next-Hop Interface"; gewählt wird der passende Eintrag mit dem längsten Präfix.
  AP2.tools.route = () => {
    const tab = area(7, ['10.10.0.0/24 lokal I_1', '10.10.9.0/28 lokal I_0', '10.10.1.0/25 10.10.9.2 I_0', '10.10.1.128/25 10.10.9.3 I_0', '10.10.2.0/27 10.10.9.4 I_0', '0.0.0.0/0 10.10.9.14 I_0'].join('\n'));
    const dest = tk.input('Ziel-IP-Adresse eines Pakets', '10.10.1.200', () => update());
    const out = box();
    const res = tk.result();
    on(tab, 'input', () => update());
    const update = () => {
      const d = ip2n(dest.get());
      const rows = tab.value.split('\n').map((l) => l.trim()).filter(Boolean).map((line) => {
        const [net, hop, ifc] = line.split(/\s+/);
        const [addr, len] = String(net).split('/');
        return {line, net, hop: hop || '?', ifc: ifc || '?', a: ip2n(addr), len: Number(len)};
      });
      const valid = rows.filter((r) => r.a !== null && r.len >= 0 && r.len <= 32);
      const hits = d === null ? [] : valid.filter((r) => ((d & mask(r.len)) >>> 0) === ((r.a & mask(r.len)) >>> 0));
      const best = hits.reduce((b, r) => (!b || r.len > b.len ? r : b), null);
      AP2.dispose(out);
      out.appendChild(AP2.blocks.table(['Ziel', 'Next Hop', 'Interface', 'passt?'], valid.map((r) => [r.net, r.hop, r.ifc, hits.includes(r) ? (r === best ? '**ja, längstes Präfix**' : 'ja') : 'nein']), {mark: best ? [valid.indexOf(best)] : []}));
      res.show(d === null ? [['Hinweis', 'Ungültige Ziel-IP']] : best ? [['Entscheidung', 'Weiterleiten über ' + best.ifc + (best.hop === 'lokal' ? ' (direkt angeschlossen)' : ' an ' + best.hop)], ['Regel', 'Von ' + hits.length + ' passenden Einträgen gewinnt der mit dem längsten Präfix (/' + best.len + ')']] : [['Entscheidung', 'Kein Eintrag passt: Paket wird verworfen (ICMP "Destination unreachable")']]);
    };
    update();
    return tk.col([tk.note('Eine Zeile je Route: Zielnetz/Präfix, Next Hop (oder "lokal"), Interface. 0.0.0.0/0 ist die Default-Route.'), tab, dest.el, out, res]);
  };

  // VLSM: größte Netze zuerst, jedes Netz so klein wie möglich, lückenlos hintereinander.
  AP2.tools.vlsm = () => {
    const base = tk.input('Startadresse/Präfix', '172.19.100.0/23', () => update());
    const needs = area(6, ['Vertrieb 106', 'Support 54', 'Produktion 30', 'Entwicklung 21', 'Leitung 10'].join('\n'));
    const out = box();
    const res = tk.result();
    on(needs, 'input', () => update());
    const update = () => {
      const [addr, plen] = base.get().split('/');
      const start = ip2n(addr);
      const blen = Number(plen);
      if (start === null || !(blen >= 0 && blen <= 32)) { AP2.dispose(out); return res.show([['Hinweis', 'Startadresse im Format a.b.c.d/Präfix']]); }
      const list = needs.value.split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const m = l.match(/^(.*?)[\s:;]+(\d+)$/); return m ? {name: m[1], hosts: Number(m[2])} : null; }).filter(Boolean)
        .sort((a, b) => b.hosts - a.hosts);
      const first = (start & mask(blen)) >>> 0;
      const end = first + 2 ** (32 - blen);
      let cur = first;
      let overflow = false;
      const rows = list.map((n) => {
        const bits = Math.max(2, Math.ceil(Math.log2(n.hosts + 2)));
        const size = 2 ** bits;
        cur = Math.ceil(cur / size) * size;
        const net = cur;
        cur += size;
        if (cur > end) overflow = true;
        return [n.name, String(n.hosts), n2ip(net) + '/' + (32 - bits), n2ip(mask(32 - bits)), n2ip(net + 1) + ' bis ' + n2ip(net + size - 2), n2ip(net + size - 1), String(size - 2)];
      });
      AP2.dispose(out);
      out.appendChild(AP2.blocks.table(['Netz', 'benötigt', 'Netz-ID/Präfix', 'Maske', 'Hostbereich', 'Broadcast', 'nutzbar'], rows));
      res.show([['Belegt bis', n2ip(cur - 1)], ['Status', overflow ? 'Der Adressraum /' + blen + ' reicht nicht aus' : 'Passt in ' + base.get()]]);
    };
    update();
    return tk.col([tk.note('Eine Zeile je Netz: Name und Anzahl benötigter Adressen (Hosts + Drucker + Router-Interface). Hosts je Netz = 2^h - 2.'), base.el, needs, out, res]);
  };

  // IPv6: Adresse als 128-Bit-BigInt.
  const v6parse = (txt) => {
    const t = txt.trim().toLowerCase();
    const halves = t.split('::');
    if (halves.length > 2) return null;
    const part = (s) => (s ? s.split(':') : []);
    const left = part(halves[0]);
    const right = halves.length === 2 ? part(halves[1]) : [];
    const fill = 8 - left.length - right.length;
    if ((halves.length === 1 && left.length !== 8) || fill < 0) return null;
    const groups = left.concat(Array(halves.length === 2 ? fill : 0).fill('0'), right);
    if (groups.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
    return groups.reduce((a, g) => (a << 16n) + BigInt(parseInt(g, 16)), 0n);
  };
  const v6full = (n) => Array.from({length: 8}, (_, i) => ((n >> BigInt(112 - 16 * i)) & 0xffffn).toString(16).padStart(4, '0'));
  const v6short = (n) => {
    const g = v6full(n).map((x) => x.replace(/^0+(?=.)/, ''));
    let best = [-1, 0];
    for (let i = 0; i < 8;) { if (g[i] === '0') { let j = i; while (j < 8 && g[j] === '0') j++; if (j - i > best[1]) best = [i, j - i]; i = j; } else i++; }
    if (best[1] < 2) return g.join(':');
    return g.slice(0, best[0]).join(':') + '::' + g.slice(best[0] + best[1]).join(':');
  };
  AP2.tools.ipv6sub = () => {
    const pre = tk.input('Zugewiesenes Präfix', '2001:db8:4a2c:1700::/56', () => update());
    const cnt = tk.input('Anzahl gleich großer Subnetze', 4, () => update(), 'number');
    const out = box();
    const res = tk.result();
    const update = () => {
      const [addr, len] = pre.get().split('/');
      const n = v6parse(addr || '');
      const L = Number(len);
      const want = Math.max(1, Math.floor(Number(cnt.get()) || 1));
      if (n === null || !(L >= 0 && L <= 128)) { AP2.dispose(out); return res.show([['Hinweis', 'Format: 2001:db8::/48']]); }
      const bits = Math.ceil(Math.log2(want));
      const nl = L + bits;
      if (nl > 128) { AP2.dispose(out); return res.show([['Hinweis', 'Zu viele Subnetze']]); }
      const netMask = L === 0 ? 0n : ((1n << 128n) - 1n) ^ ((1n << BigInt(128 - L)) - 1n);
      const base = n & netMask;
      const step = 1n << BigInt(128 - nl);
      const rows = [];
      for (let i = 0; i < Math.min(2 ** bits, 16); i++) {
        const s = base + BigInt(i) * step;
        rows.push(['Subnetz ' + (i + 1), v6short(s) + '/' + nl, v6full(s).slice(0, 4).join(':'), v6short(s + step - 1n)]);
      }
      AP2.dispose(out);
      out.appendChild(AP2.blocks.table(['Name', 'Präfix', 'erste 64 Bit (ausgeschrieben)', 'letzte Adresse'], rows));
      res.show([['Rechnung', 'Für ' + want + ' Subnetze braucht man ' + bits + ' Bit (2^' + bits + ' = ' + 2 ** bits + '), neues Präfix /' + L + ' + ' + bits + ' = /' + nl], ['Schrittweite', nl % 4 === 0 ? 'Hexziffer an Bitposition ' + nl + ' zählt hoch' : '2^' + (128 - nl) + ' Adressen je Subnetz'], ['Subnetze gesamt', String(2 ** bits) + (2 ** bits > 16 ? ' (die ersten 16 angezeigt)' : '')]]);
    };
    update();
    return tk.col([tk.note('Neues Präfix = altes Präfix + n, wenn 2^n Subnetze gebraucht werden. Jede Hexziffer entspricht 4 Bit.'), tk.row([pre.el, cnt.el]), out, res]);
  };
})();
;
// content/ps/plausibilitaet-1.js
AP2.page('ps-plausibilitaet', {
  b: 'ps', g: 'Softwareentwurf', t: 'Plausibilitätsprüfung und Fehlerbehandlung (Messwerte, Eingaben)',
  d: 'Eine **Plausibilitätsprüfung** testet, ob ein Wert **sinnvoll** sein kann. Beispiel: Eine Akkuspannung von 400 Volt ist bei einem Handy-Akku **unmöglich**. Die Prüfung liefert **true** (Wert ist plausibel) oder **false** (Wert ist ungültig). Sie ist **keine** Prüfung auf Richtigkeit: Ein plausibler Wert kann trotzdem falsch sein.',
  m: '**Plausibel heißt: möglich, nicht: richtig.** Prüfe **Typ**, **Wertebereich** (Minimum bis Maximum), **Pflichtfeld** und **Format**. Ungültige Werte **nicht still ändern**: ablehnen, melden oder herausfiltern.',
  cheat: [
    ['Prüfarten', ['**Typ:** Ist es eine Zahl?', '**Bereich:** min <= Wert <= max', '**Pflichtfeld:** nicht leer', '**Format:** z. B. Datum, E-Mail', '**Abhängigkeit:** Ende nach Anfang']],
    ['Reaktion', ['Wert **ablehnen** und Fehlermeldung zeigen', 'Wert **herausfiltern** (Liste bereinigen)', 'Fehler **protokollieren** (Log)']],
    ['Prüfungsfallen', ['Grenzwerte: gilt <= oder <?', 'Plausibel ist nicht gleich richtig', 'Prüfung gehört in die Klasse, die die Daten besitzt']],
  ],
  blocks: [
    ['h', 'Was ist das und warum braucht man es?'],
    ['p', 'Sensoren und Benutzer liefern manchmal falsche Daten. Ein Kabel wackelt. Jemand tippt eine Null zu viel. Wenn das Programm diese Werte speichert, werden spätere Berechnungen falsch.'],
    ['p', 'Darum prüft das Programm jeden Wert **vor** dem Speichern. Das nennt man **Plausibilitätsprüfung** (Plausibilität = „das kann sein“).'],
    ['table', ['Wort', 'Einfach erklärt'], [
      ['plausibel', 'möglich, sinnvoll, passt zur Realität'],
      ['Messwert', 'Zahl, die ein Sensor gemessen hat (z. B. Spannung in Volt)'],
      ['Wertebereich', 'Von-bis-Grenzen, in denen ein Wert liegen darf'],
      ['Grenzwert', 'kleinster oder größter erlaubter Wert'],
      ['filtern', 'ungültige Werte aus einer Liste entfernen'],
      ['Ausreißer', 'Wert, der stark von allen anderen abweicht'],
    ]],
    ['h', 'Beispiel Schritt für Schritt'],
    ['p', 'Ein Messgerät prüft einen Akku. Spannungswerte liegen bei diesem Akku zwischen **2,5 V** (leer) und **4,2 V** (voll). Die Methode `pruefeWert()` soll sagen, ob ein Wert möglich ist.'],
    ['code', 'java', `boolean pruefeWert(double spannung) {
    // Wertebereich des Akkus: 2,5 V bis 4,2 V (Grenzen sind erlaubt)
    return spannung >= 2.5 && spannung <= 4.2;
}`],
    ['table', ['Messwert', 'Prüfung', 'Ergebnis'], [
      ['3,7 V', '3,7 >= 2,5 und 3,7 <= 4,2', '**true**'],
      ['4,2 V', 'Grenzwert: <= erlaubt', '**true**'],
      ['4,3 V', '4,3 <= 4,2 ist falsch', '**false**'],
      ['0,0 V', '0,0 >= 2,5 ist falsch (Kabel ab?)', '**false**'],
      ['-1 V', 'kleiner als Minimum', '**false**'],
    ]],
    ['h', 'Liste bereinigen (filtern)'],
    ['p', 'Oft soll eine ganze Liste geprüft werden. Die Methode entfernt ungültige Werte und gibt zurück, **wie viele** sie entfernt hat. Wichtig: Beim Entfernen in einer Schleife von **hinten nach vorne** laufen. So verschiebt sich kein Index.'],
    ['code', 'java', `int bereinige(List<Double> werte) {
    int entfernt = 0;
    for (int i = werte.size() - 1; i >= 0; i--) {
        if (!pruefeWert(werte.get(i))) {
            werte.remove(i);
            entfernt++;
        }
    }
    return entfernt;
}`],
    ['table', ['Schritt i', 'Wert', 'Gültig?', 'Aktion', 'entfernt'], [
      ['3', '4,9', 'nein', 'löschen', '1'],
      ['2', '3,6', 'ja', '-', '1'],
      ['1', '0,0', 'nein', 'löschen', '2'],
      ['0', '3,8', 'ja', '-', '2'],
    ]],
    ['note', 'Liste vorher: [3,8; 0,0; 3,6; 4,9]. Nachher: [3,8; 3,6]. Rückgabe: 2.'],
    ['h', 'Wann wird bereinigt?'],
    ['p', 'Typische Prüfungsfrage: **Wann** ruft man die Bereinigung auf? Antwort mit Begründung: **Nach** der Messung, aber **vor** der Auswertung (Mittelwert, Kapazität, Diagramm). Sonst verfälschen ungültige Werte das Ergebnis. Eine Ausnahme: Wenn man die Rohdaten für Fehlersuche braucht, speichert man sie vorher getrennt.'],
    ['h', 'Prüfungsfallen'],
    ['warn', '**Plausibel ist nicht richtig.** Eine Spannung von 3,9 V ist plausibel. Sie kann trotzdem falsch gemessen sein. Die Prüfung findet nur **unmögliche** Werte.'],
    ['warn', '**Grenzen genau lesen.** „von 2,5 bis 4,2 V“ heißt meist: Grenzen **gehören dazu** (>= und <=). Schreibe die Annahme in die Antwort.'],
    ['tip', 'Im Struktogramm ist die Prüfung eine **Verzweigung** (Raute). Ungültig: Fehlerpfad (ablehnen, zählen). Gültig: weiterverarbeiten.'],
    ['h', 'Aufgaben im Prüfungsstil'],
    ['qa', '**Erläutern** Sie, warum eine Plausibilitätsprüfung nicht beweist, dass ein Messwert richtig ist.', ['Sie prüft nur, ob der Wert **im möglichen Bereich** liegt.', 'Ein falsch gemessener Wert kann trotzdem im Bereich liegen, z. B. 3,9 V statt 3,7 V.'], 2],
    ['qa', '**Nennen** Sie drei Arten von Plausibilitätsprüfungen.', ['Wertebereich (min bis max)', 'Typ/Format (Zahl, Datum)', 'Pflichtfeld oder Abhängigkeit (Ende nach Anfang)'], 3],
    ['qa', '**Begründen** Sie, warum man beim Löschen aus einer Liste von hinten nach vorne läuft.', ['Beim Löschen rücken alle späteren Elemente einen Platz nach vorne.', 'Läuft man von vorne, überspringt man dadurch Elemente.'], 2],
    ['see', ['ps-struktogramm', 'ps-testarten', 'ps-klassen']],
    ['quiz', [
      {q: 'Was prüft eine Plausibilitätsprüfung?', o: ['Ob ein Wert möglich und sinnvoll ist', 'Ob ein Wert exakt richtig ist', 'Ob das Programm schnell ist', 'Ob der Code schön ist'], a: 0, e: 'Sie erkennt unmögliche Werte, beweist aber nicht die Richtigkeit.'},
      {q: 'Bereich 2,5 bis 4,2 V, Grenzen erlaubt. Ist 4,2 V gültig?', o: ['Ja', 'Nein', 'Nur bei Entladung', 'Nur als Mittelwert'], a: 0, e: 'Mit <= ist der Grenzwert 4,2 gültig.'},
      {q: 'Welche Reaktion ist bei einem ungültigen Messwert sinnvoll?', o: ['Ablehnen oder herausfiltern und melden', 'Still auf 0 setzen', 'Einfach speichern', 'Programm löschen'], a: 0, e: 'Ungültige Werte dürfen die Auswertung nicht verfälschen.'},
      {q: 'Wann bereinigt man eine Messwertliste sinnvoll?', o: ['Nach der Messung, vor der Auswertung', 'Nie', 'Nach der Auswertung', 'Vor dem Einschalten des Sensors'], a: 0, e: 'Sonst fließen Fehlwerte in Mittelwert oder Kapazität ein.'},
    ]],
  ],
});
;
// content/ps/dbzugriff-1.js
AP2.page('ps-dbzugriff', {
  b: 'ps', g: 'Datenbanken', t: 'Datenbankzugriff aus dem Programm: Verbindung, ERM aus Script, REST',
  d: 'Ein Programm spricht mit einer Datenbank über eine **Verbindung**. Dafür braucht es einen **Connection-String** (Verbindungszeichenfolge) mit den **Angaben**: wo läuft die Datenbank, wie heißt sie, wer darf zugreifen. Aus einem **SQL-Script** (CREATE TABLE) kann man das **ERM** ablesen: Jeder **FOREIGN KEY** ist eine Beziehung. Ein **REST-Service** gibt Daten über **HTTP(S)** meist im Format **JSON** weiter.',
  m: '**Connection-String = Server, Port, Datenbankname, Benutzer, Passwort** (und evtl. Treiber/SSL). **FOREIGN KEY in Tabelle B auf A = Beziehung A 1 : n B.** **REST = HTTP(S) + JSON.**',
  cheat: [
    ['Connection-String', ['**Server/Host** (Name oder IP)', '**Port** (MySQL 3306)', '**Datenbankname**', '**Benutzer** und **Passwort**', 'Treiber, Zeichensatz, SSL (optional)']],
    ['ERM aus Script', ['Jede **CREATE TABLE** = ein Entitätstyp', '**PRIMARY KEY** = Identifikator', '**FOREIGN KEY** = Beziehung (n-Seite hat den Fremdschlüssel)', 'Tabelle mit **zwei** Fremdschlüsseln im Schlüssel = Auflösung einer **n:m**-Beziehung']],
    ['REST', ['Protokoll: **HTTP/HTTPS**', 'Format meist **JSON**', 'GET lesen, POST anlegen, PUT ändern, DELETE löschen']],
  ],
  blocks: [
    ['h', 'Wie kommt ein Programm an die Daten?'],
    ['p', 'Ein Java- oder C#-Programm liest Tabellen nicht direkt von der Festplatte. Es baut eine **Verbindung** zum Datenbankserver auf. Dann sendet es SQL-Befehle und bekommt die Ergebnisse zurück.'],
    ['table', ['Wort', 'Einfach erklärt'], [
      ['Connection-String', 'Text mit allen Angaben für die Verbindung'],
      ['Port', 'Nummer des „Eingangs“ am Server (MySQL: 3306)'],
      ['Treiber', 'Programmteil, der die Sprache der Datenbank spricht'],
      ['Fremdschlüssel', 'Spalte, die auf den Schlüssel einer anderen Tabelle zeigt'],
      ['Anomalie', 'Fehler durch doppelte Daten (Einfüge-, Änderungs-, Löschanomalie)'],
    ]],
    ['h', 'Connection-String: Parameter nennen'],
    ['code', 'text', `Server=192.168.10.20;Port=3306;Database=angebote;Uid=appuser;Pwd=geheim;`],
    ['table', ['Parameter', 'Bedeutung', 'Beispiel'], [
      ['Server / Host', 'Wo läuft die Datenbank?', '192.168.10.20 oder db.firma.de'],
      ['Port', 'Welcher Dienst-Eingang?', '3306'],
      ['Database', 'Welche Datenbank auf dem Server?', 'angebote'],
      ['Uid / User', 'Benutzername', 'appuser'],
      ['Pwd / Password', 'Passwort', '(nie im Quelltext speichern!)'],
    ]],
    ['warn', 'Passwörter gehören **nicht** in den Quelltext. Besser: Konfigurationsdatei oder Umgebungsvariable. Der Benutzer bekommt nur die **nötigen Rechte** (Prinzip der minimalen Rechte).'],
    ['h', 'ERM aus einem SQL-Script ablesen'],
    ['p', 'Aufgabe: „Erstellen Sie das ERM ohne Attribute.“ Gehe so vor:'],
    ['steps', [
      'Zeichne für **jede Tabelle** ein Rechteck (Entitätstyp).',
      'Suche alle **FOREIGN KEY**-Zeilen. Die Tabelle **mit** dem Fremdschlüssel ist die **n-Seite**.',
      'Zeichne eine Linie zur Tabelle, auf die der Schlüssel zeigt. Das ist die **1-Seite**.',
      'Hat eine Tabelle **zwei** Fremdschlüssel und besteht nur daraus, ist sie die **Verbindungstabelle** einer **n:m**-Beziehung. Zeichne sie als n:m zwischen den beiden Tabellen.',
      'Schreibe an jede Linie die Kardinalität (1, n) und ein Verb (z. B. „erhält“).',
    ]],
    ['code', 'sql', `CREATE TABLE patient (pid INT PRIMARY KEY, name VARCHAR(40));
CREATE TABLE befund  (bid INT PRIMARY KEY, pid INT,
  FOREIGN KEY (pid) REFERENCES patient(pid));`],
    ['p', '`befund` hat den Fremdschlüssel `pid`. Also: **patient 1 : n befund**. Ein Patient hat viele Befunde, ein Befund gehört zu einem Patienten.'],
    ['diagram', {w: 520, h: 140, keep: 400, cap: 'ERM zum Script: patient 1 : n befund.', nodes: [
      {id: 'p', x: 60, y: 40, k: 'box', t: 'Patient', w: 140, h: 50},
      {id: 'b', x: 320, y: 40, k: 'box', t: 'Befund', w: 140, h: 50},
    ], edges: [{a: 'p', b: 'b', ta: '1', tb: 'n', t: 'erhält'}]}],
    ['h', 'REST-Service für Sensordaten'],
    ['p', 'Ein **REST-Service** stellt Daten für andere Programme bereit. Ein Client schickt eine **HTTP-Anfrage**, der Server antwortet mit **JSON**.'],
    ['table', ['Anfrage', 'Bedeutung'], [
      ['GET /sensoren/7', 'Sensor 7 lesen'],
      ['POST /sensoren', 'neuen Sensor anlegen'],
      ['PUT /sensoren/7', 'Sensor 7 ändern'],
      ['DELETE /sensoren/7', 'Sensor 7 löschen'],
    ]],
    ['code', 'json', `{ "id": 7, "typ": "Temperatur", "wert": 71.5, "einheit": "Grad C" }`],
    ['tip', 'Prüfungsantwort kurz: Protokoll **HTTP(S)**. Datenformat **JSON** (JavaScript Object Notation). HTTPS, weil die Daten **verschlüsselt** übertragen werden.'],
    ['h', 'Aufgaben im Prüfungsstil'],
    ['qa', '**Nennen** Sie vier Parameter eines Connection-Strings.', ['Server/Host', 'Port', 'Datenbankname', 'Benutzername und Passwort'], 4],
    ['qa', '**Erläutern** Sie, woran man im SQL-Script eine 1:n-Beziehung erkennt.', ['Eine Tabelle enthält einen **FOREIGN KEY**.', 'Diese Tabelle ist die **n-Seite**, die referenzierte Tabelle die **1-Seite**.'], 2],
    ['qa', '**Benennen** Sie Protokoll und Datenformat einer REST-Schnittstelle.', ['HTTP bzw. HTTPS', 'JSON (seltener XML)'], 2],
    ['see', ['ps-er', 'ps-relational', 'ps-normalisierung', 'eua-sqler', 'eua-webapi']],
    ['quiz', [
      {q: 'Welche Angabe gehört NICHT in einen Connection-String?', o: ['Farbe der Oberfläche', 'Server', 'Datenbankname', 'Benutzername'], a: 0, e: 'Der String enthält nur Angaben für die Verbindung.'},
      {q: 'Tabelle B hat einen FOREIGN KEY auf Tabelle A. Welche Beziehung?', o: ['A 1 : n B', 'A n : 1 A', 'B 1 : n A', 'keine'], a: 0, e: 'Die Tabelle mit dem Fremdschlüssel ist die n-Seite.'},
      {q: 'Welches Protokoll nutzt REST meist?', o: ['HTTP/HTTPS', 'SMTP', 'DHCP', 'ARP'], a: 0, e: 'REST nutzt die HTTP-Methoden GET, POST, PUT, DELETE.'},
      {q: 'Welches Format liefert ein REST-Service meist?', o: ['JSON', 'EXE', 'MP3', 'BMP'], a: 0, e: 'JSON ist leicht lesbar und kompakt.'},
    ]],
  ],
});
;
// content/ps/phasen-1.js
AP2.page('ps-phasen', {
  b: 'ps', g: 'Projektmanagement', t: 'Projektphasen',
  d: 'Ein **Projekt** ist ein einmaliges Vorhaben mit klarem Ziel, festem Zeitrahmen, begrenzten Mitteln (Geld, Personal) und einer eigenen Organisation. Ein Projekt läuft in **Phasen**: Initiierung, Planung, Durchführung und Abschluss.',
  m: '**I-P-D-A**: Initiierung, Planung, Durchführung, Abschluss. Das Magische Dreieck: **Z-K-Q** = Zeit, Kosten, Qualität. Wenn man an einer Ecke zieht, verändern sich die anderen. Projektziele sind **SMART**: **S**pezifisch, **M**essbar, **A**ttraktiv (akzeptiert), **R**ealistisch, **T**erminiert.',
  cheat: [
    ['Merkmale eines Projekts', ['Einmalig (kein Tagesgeschäft)', 'Zeitlich begrenzt (Start und Ende)', 'Klares Ziel und Ergebnis', 'Begrenzte Ressourcen', 'Projektorganisation, oft neuartig und riskant']],
    ['Die vier Phasen', ['**Initiierung**: Idee, **SMART-Ziel**, Projektauftrag', '**Planung**: Struktur, Zeit, Kosten, Risiken', '**Durchführung**: Umsetzen, steuern, kontrollieren', '**Abschluss**: Abnahme, Übergabe, Lessons Learned']],
    ['SMART-Ziele', ['**S**pezifisch: eindeutig und konkret', '**M**essbar: mit Zahl oder Prüfkriterium', '**A**ttraktiv / akzeptiert: von den Beteiligten gewollt', '**R**ealistisch: mit den Mitteln erreichbar', '**T**erminiert: mit festem Datum']],
    ['Magisches Dreieck', ['Zeit, Kosten, Qualität (plus Umfang/Scope)', 'Alle drei hängen zusammen', 'Mehr Qualität kostet Zeit oder Geld', 'Termin kürzen: Kosten steigen oder Umfang sinkt']],
    ['Rollen', ['**Auftraggeber** (bestellt und bezahlt)', '**Projektleiter** (plant und steuert)', '**Projektteam** (arbeitet)', '**Stakeholder** (alle Betroffenen und Interessierten)']],
  ],
  blocks: [
    ['h', 'Was ist ein Projekt?'],
    ['p', 'Im Alltag eines Unternehmens gibt es zwei Arten von Arbeit. Das **Tagesgeschäft** wiederholt sich (zum Beispiel Rechnungen schreiben, Server überwachen). Ein **Projekt** dagegen passiert nur einmal. Beispiel: "Wir entwickeln eine neue Kundenverwaltung bis zum 30. September mit 120.000 Euro Budget."'],
    ['p', 'Nach **DIN 69901** ist ein Projekt ein Vorhaben, das im Wesentlichen durch die **Einmaligkeit der Bedingungen** gekennzeichnet ist. Dazu gehören eine Zielvorgabe, zeitliche, finanzielle und personelle Begrenzungen, die Abgrenzung zu anderen Vorhaben und eine projektspezifische Organisation.'],
    ['table', ['Kriterium', 'Projekt', 'Tagesgeschäft (Routine)'], [
      ['Dauer', 'Befristet, mit Start und Ende', 'Dauerhaft'],
      ['Ablauf', 'Einmalig, neu', 'Wiederholt sich'],
      ['Risiko', 'Höher, weil neu', 'Gering, weil bekannt'],
      ['Organisation', 'Eigenes Team, oft aus mehreren Abteilungen', 'Feste Abteilung'],
      ['Beispiel', 'Einführung einer Web-Shop-Software', 'Wöchentliche Datensicherung prüfen'],
    ]],
    ['h', 'Das Magische Dreieck'],
    ['p', 'Jedes Projekt wird an drei Größen gemessen: **Zeit** (Termin), **Kosten** (Budget) und **Qualität** (Leistung, Funktionsumfang). Diese Größen hängen voneinander ab. Das nennt man **Magisches Dreieck** (englisch: Iron Triangle).'],
    ['diagram', {w: 720, h: 330, cap: 'Magisches Dreieck: Wer an einer Ecke zieht, verändert die anderen.', nodes: [
      {id: 'z', x: 360, y: 40, t: ['Zeit', 'Termin einhalten'], k: 'round', s: 'accent', w: 190, h: 56},
      {id: 'k', x: 130, y: 270, t: ['Kosten', 'Budget einhalten'], k: 'round', s: 'accent', w: 190, h: 56},
      {id: 'q', x: 590, y: 270, t: ['Qualität', 'Umfang und Güte'], k: 'round', s: 'accent', w: 190, h: 56},
      {id: 'm', x: 360, y: 190, t: ['Projekterfolg'], k: 'oval', s: 'solid', w: 150, h: 54},
    ], edges: [
      {a: 'z', b: 'k', ea: 'none', t: 'schneller = teurer'}, {a: 'k', b: 'q', ea: 'none', t: 'günstiger = weniger Qualität'}, {a: 'q', b: 'z', ea: 'none', t: 'mehr Umfang = mehr Zeit'},
      {a: 'm', b: 'z', ea: 'none', k: 'dash'}, {a: 'm', b: 'k', ea: 'none', k: 'dash'}, {a: 'm', b: 'q', ea: 'none', k: 'dash'},
    ]}],
    ['tip', 'Typische Prüfungsfrage: "Das Projekt hat Verzug. Nennen Sie Maßnahmen." Antwort immer mit dem Dreieck begründen: mehr Personal (Kosten steigen), Funktionsumfang kürzen (Qualität/Umfang sinkt) oder Termin verschieben (Zeit steigt).'],
  ],
});
;
// content/ps/phasen-2.js
AP2.add('ps-phasen', [
  ['h', 'Die vier Phasen im Detail'],
  ['diagram', AP2.dg.flow(['Initiierung', 'Planung', 'Durchführung', 'Abschluss'], {h: 100, styles: ['accent', 'accent', 'accent', 'accent'], edgeText: ['Auftrag', 'Plan', 'Ergebnis'], cap: 'Der Projektablauf als Kette von Phasen mit Meilensteinen dazwischen.'})],
  ['h3', '1. Initiierung (Start)'],
  ['p', 'Hier entsteht die Idee. Man klärt: Was ist das Problem? Was ist das Ziel? Lohnt sich das Projekt? Am Ende steht der **Projektauftrag** (englisch: project charter). Er enthält das **SMART formulierte Ziel**, grobe Kosten, Termin, Projektleiter und Befugnisse.'],
  ['list', ['**Ergebnisse:** Projektauftrag, Machbarkeitsstudie, Stakeholder-Liste, Ist-Analyse', '**Wichtige Methoden:** Zielformulierung nach **SMART**, Wirtschaftlichkeitsbetrachtung (Kosten-Nutzen), Stakeholder-Analyse, grobe Risikoabschätzung']],
  ['h3', 'Projektziele nach SMART formulieren'],
  ['p', 'Ein Ziel wie "Die Kundenverwaltung soll besser werden" lässt sich weder planen noch am Ende abnehmen. Deshalb wird das Projektziel in der Initiierung nach der **SMART-Regel** formuliert und so in den Projektauftrag geschrieben. Die Planung leitet daraus Arbeitspakete und Meilensteine ab, die Durchführung misst den Fortschritt daran, und beim Abschluss ist es der Maßstab für die **Abnahme**.'],
  ['table', ['Buchstabe', 'Bedeutung', 'Prüffrage', 'Beispiel'], [
    ['**S**', '**Spezifisch**', 'Ist eindeutig, was genau erreicht werden soll?', 'Eine webbasierte Kundenverwaltung löst die Excel-Listen im Vertrieb ab'],
    ['**M**', '**Messbar**', 'Woran erkennt man, dass das Ziel erreicht ist?', 'Alle 4.200 Kundendatensätze sind übernommen, eine Suche dauert unter 2 Sekunden'],
    ['**A**', '**Attraktiv** (akzeptiert, auch: ausführbar, erreichbar)', 'Wollen Auftraggeber und Team dieses Ziel?', 'Der Vertrieb hat die Anforderungen im Workshop bestätigt'],
    ['**R**', '**Realistisch**', 'Ist es mit Zeit, Budget und Personal machbar?', 'Drei Entwickler, 120.000 Euro Budget, Technik im Haus bekannt'],
    ['**T**', '**Terminiert**', 'Bis wann ist es erreicht?', 'Produktivstart am 30. September'],
  ]],
  ['ex', ['**Nicht SMART:** "Wir wollen die Kundenverwaltung modernisieren."', '**SMART:** "Bis zum **30. September** ist die webbasierte Kundenverwaltung im Vertrieb produktiv, **alle 4.200 Kundendatensätze** sind aus den Excel-Listen übernommen, eine Kundensuche dauert **höchstens 2 Sekunden**, und das Budget von **120.000 Euro** wird eingehalten."']],
  ['table', ['Phase', 'Wofür das SMART-Ziel gebraucht wird'], [
    ['Initiierung', 'Ziel formulieren und im **Projektauftrag** festhalten'],
    ['Planung', 'Aus dem Ziel Arbeitspakete, Termine und **Meilensteine** ableiten (auch Meilensteine sind messbar und terminiert)'],
    ['Durchführung', '**Soll-Ist-Vergleich**: Die Messgrößen des Ziels sind das Soll'],
    ['Abschluss', '**Abnahme**: Die Messgrößen sind die Abnahmekriterien'],
  ]],
  ['warn', 'Die Buchstaben **A** und **R** werden je nach Quelle unterschiedlich übersetzt: A = attraktiv, akzeptiert, ausführbar oder erreichbar (achievable); R = realistisch oder relevant. In der Prüfung reicht **eine** gängige Variante, aber A und R dürfen nicht dasselbe bedeuten. Sicher ist: **S**pezifisch, **M**essbar, **A**ttraktiv/akzeptiert, **R**ealistisch, **T**erminiert.'],
  ['h3', '2. Planung'],
  ['p', 'Der Projektleiter zerlegt das Projekt in kleine, überschaubare Teile und plant Zeit, Kosten, Personal und Risiken. Je besser die Planung, desto weniger Überraschungen später.'],
  ['list', ['**Projektstrukturplan (PSP):** Zerlegung in Teilaufgaben und Arbeitspakete (was?)', '**Ablauf- und Terminplan:** Reihenfolge, Dauer, Netzplan, Gantt-Diagramm (wann?)', '**Kosten- und Ressourcenplan:** Personal, Material, Budget (womit, wie viel?)', '**Risikoplan:** Was kann schiefgehen? Wie reagieren wir? (Risikoanalyse)', '**Qualitäts- und Kommunikationsplan:** Wer berichtet wem wann?']],
  ['h3', '3. Durchführung (Steuerung)'],
  ['p', 'Jetzt wird gearbeitet. Gleichzeitig vergleicht der Projektleiter ständig **Soll** (Plan) und **Ist** (Realität). Weicht es ab, steuert er gegen. Das nennt man **Projektcontrolling**.'],
  ['list', ['**Fortschrittskontrolle:** Meilensteintrendanalyse, Statusberichte, Soll-Ist-Vergleich', '**Änderungsmanagement (Change Requests):** Neue Wünsche werden bewertet, nicht einfach eingebaut', '**Risikomanagement läuft weiter** und die Dokumentation wird aktuell gehalten']],
  ['h3', '4. Abschluss'],
  ['p', 'Das Ergebnis wird vom Kunden **abgenommen** (Abnahmeprotokoll). Dann folgt die Übergabe (Handbuch, Schulung, Betrieb) und die **Abschlussbesprechung** mit Lessons Learned: Was lief gut? Was lief schlecht? Was machen wir beim nächsten Projekt anders?'],
  ['table', ['Phase', 'Leitfrage', 'Typisches Ergebnis'], [
    ['Initiierung', 'Was wollen wir und lohnt es sich?', 'Projektauftrag mit SMART-Ziel'],
    ['Planung', 'Wie, wann, womit machen wir es?', 'Projektplan (PSP, Netzplan, Budget)'],
    ['Durchführung', 'Sind wir im Plan?', 'Zwischenergebnisse, Statusberichte'],
    ['Abschluss', 'Haben wir erreicht, was vereinbart war?', 'Abnahmeprotokoll, Abschlussbericht'],
  ]],
  ['note', 'In DIN 69901 werden fünf Phasen genannt: Initialisierung, Definition, Planung, Steuerung, Abschluss. Die vier Phasen hier sind eine übliche Vereinfachung (Definition und Planung zusammen, Steuerung = Durchführung). Nenne in der Prüfung die Phasen, die in der Aufgabe vorkommen.'],
  ['h', 'Meilensteine'],
  ['p', 'Ein **Meilenstein** ist ein wichtiger Zeitpunkt ohne Dauer, an dem ein Ergebnis fertig sein muss, zum Beispiel "Pflichtenheft abgenommen" oder "Test abgeschlossen". Meilensteine dienen als Kontrollpunkte (englisch: Quality Gates): Hier entscheidet der Auftraggeber, ob das Projekt weitergeht.'],
  ['warn', 'Ein Meilenstein hat **keine Dauer** (0 Tage). Ein Vorgang oder Arbeitspaket dagegen hat immer eine Dauer.'],
]);
;
// content/ps/phasen-3.js
AP2.add('ps-phasen', [
  ['h', 'Aufgaben im Prüfungsstil'],
  ['qa', 'Nennen Sie vier Merkmale eines Projekts und grenzen Sie es vom Tagesgeschäft ab.', ['- Einmaligkeit: Das Vorhaben ist neu und läuft nur einmal, das Tagesgeschäft wiederholt sich.', '- Zeitliche Begrenzung: Ein Projekt hat Start und Ende, das Tagesgeschäft ist dauerhaft.', '- Klare Zielvorgabe: Es gibt ein definiertes Ergebnis.', '- Begrenzte Ressourcen und eigene Projektorganisation (Team, Budget).'], 4],
  ['qa', 'Das Magische Dreieck besteht aus drei Größen. Nennen Sie diese und erklären Sie an einem Beispiel, wie sie sich beeinflussen.', ['Zeit, Kosten und Qualität (Umfang).', 'Beispiel: Der Kunde möchte den Fertigstellungstermin um zwei Wochen vorziehen. Dann sind mehr Entwickler nötig (**Kosten steigen**) oder es werden weniger Funktionen geliefert (**Umfang/Qualität sinkt**). Beides gleichzeitig zu vermeiden ist nicht möglich.'], 4],
  ['qa', 'Ordnen Sie die folgenden Tätigkeiten den Projektphasen zu: a) Abnahmeprotokoll unterschreiben, b) Netzplan erstellen, c) Projektauftrag formulieren, d) Soll-Ist-Vergleich der Kosten.', ['- a) Abschluss', '- b) Planung', '- c) Initiierung', '- d) Durchführung (Projektcontrolling)'], 4],
  ['qa', 'Erläutern Sie die SMART-Regel und formulieren Sie das Ziel "Die Website soll schneller werden" SMART.', ['- **S**pezifisch: Das Ziel ist eindeutig und konkret beschrieben.', '- **M**essbar: Es gibt eine Zahl oder ein Kriterium, an dem die Zielerreichung geprüft wird.', '- **A**ttraktiv (akzeptiert): Die Beteiligten wollen das Ziel erreichen.', '- **R**ealistisch: Es ist mit den vorhandenen Mitteln erreichbar.', '- **T**erminiert: Es hat einen festen Endtermin.', '**SMART formuliert:** "Bis zum 30. Juni lädt die Startseite des Webshops auf einem üblichen Mobilgerät in höchstens 2 Sekunden (heute 5 Sekunden). Zwei Entwickler setzen dafür Bildkomprimierung und Caching um."'], 7],
  ['qa', 'Prüfen Sie das Ziel "Wir führen bald ein modernes Ticketsystem ein" anhand der SMART-Kriterien.', ['- **Spezifisch:** nein, "modern" sagt nicht, welche Funktionen und für welche Abteilung.', '- **Messbar:** nein, es fehlt ein Kriterium (zum Beispiel "alle Supportanfragen werden als Ticket erfasst").', '- **Attraktiv/akzeptiert:** nicht erkennbar, die Beteiligten sind nicht genannt.', '- **Realistisch:** nicht prüfbar, weil Umfang und Mittel fehlen.', '- **Terminiert:** nein, "bald" ist kein Termin.', 'Das Ziel ist **nicht SMART**. Besser: "Bis zum 1. März erfasst der IT-Support alle Anfragen im neuen Ticketsystem, 95 Prozent der Tickets erhalten innerhalb von 4 Stunden eine erste Antwort."'], 6],
  ['qa', 'Was ist ein Meilenstein und wozu dient er?', 'Ein Meilenstein ist ein wichtiger Zeitpunkt ohne Dauer, an dem ein bestimmtes Zwischenergebnis fertig sein muss. Er dient als Kontrollpunkt, an dem der Projektfortschritt geprüft und über das Weitermachen entschieden wird.', 2],
  ['h', 'Selbsttest'],
  ['quiz', [
    {q: 'Welche Phase steht am Anfang eines Projekts und endet mit dem Projektauftrag?', o: ['Initiierung', 'Planung', 'Durchführung', 'Abschluss'], a: 0, e: 'Die Initiierung klärt Idee und Ziel und endet mit dem Projektauftrag. Danach folgt die Planung.'},
    {q: 'Wofür steht das M in SMART?', o: ['Messbar', 'Motivierend', 'Machbar', 'Modular'], a: 0, e: 'Spezifisch, Messbar, Attraktiv (akzeptiert), Realistisch, Terminiert.'},
    {q: 'Welches SMART-Kriterium fehlt dem Ziel "Die App soll 500 Nutzer gleichzeitig bedienen können"?', o: ['Terminiert', 'Messbar', 'Spezifisch', 'Keines'], a: 0, e: 'Es gibt eine Messgröße (500 Nutzer), aber keinen Termin, bis wann das erreicht sein soll.'},
    {q: 'In welcher Projektphase wird das Projektziel SMART formuliert?', o: ['Initiierung', 'Durchführung', 'Abschluss', 'Nach der Abnahme'], a: 0, e: 'Das Ziel gehört in den Projektauftrag, der am Ende der Initiierung steht.'},
    {q: 'Was gehört NICHT zum Magischen Dreieck?', o: ['Zeit', 'Kosten', 'Qualität', 'Mitarbeiterzufriedenheit'], a: 3, e: 'Das Dreieck besteht aus Zeit, Kosten und Qualität. Mitarbeiterzufriedenheit ist wichtig, aber nicht Teil des Modells.'},
    {q: 'Welche Aussage über Meilensteine stimmt?', o: ['Sie haben keine Dauer und markieren ein Zwischenergebnis.', 'Sie dauern immer genau eine Woche.', 'Sie beschreiben das Gehalt des Projektleiters.', 'Sie werden erst nach dem Abschluss festgelegt.'], a: 0, e: 'Ein Meilenstein ist ein Zeitpunkt (Dauer 0), kein Vorgang. Er wird schon in der Planung festgelegt.'},
    {q: 'In welcher Phase findet der Soll-Ist-Vergleich statt?', o: ['Durchführung', 'Initiierung', 'Nur beim Abschluss', 'Vor der Projektidee'], a: 0, e: 'Während der Durchführung wird laufend kontrolliert, ob Plan (Soll) und Realität (Ist) übereinstimmen.'},
    {q: 'Warum ist die Wartung einer bestehenden Datenbank (jede Woche gleich) meist KEIN Projekt?', o: ['Sie ist wiederkehrend und dauerhaft, also Tagesgeschäft.', 'Weil sie zu teuer ist.', 'Weil sie keinen Auftraggeber hat.', 'Weil Datenbanken nie Projekte sind.'], a: 0, e: 'Projekte sind einmalig und befristet. Wiederkehrende Aufgaben sind Routine.'},
  ]],
]);
;
// content/ps/vorgehen-1.js
AP2.page('ps-vorgehen', {
  b: 'ps', g: 'Projektmanagement', t: 'Vorgehensmodelle (Wasserfall, V-Modell, agil)',
  d: 'Ein **Vorgehensmodell** legt fest, in welcher Reihenfolge und mit welchen Regeln ein Softwareprojekt abläuft. **Klassische Modelle** (Wasserfall, V-Modell) arbeiten Phase für Phase nacheinander. **Agile Modelle** (Scrum, Kanban) liefern in kurzen Zyklen lauffähige Teilergebnisse.',
  m: '**Wasserfall** = Wasser fließt nur nach unten, kein Zurück. **V-Modell** = jede Entwurfsstufe hat links ihre Teststufe rechts. **Agil** = kleine Schritte, oft liefern, oft Feedback.',
  cheat: [
    ['Wasserfall', ['Phasen strikt nacheinander', 'Gut bei festen, klaren Anforderungen', 'Änderungen spät sehr teuer', 'Kunde sieht Ergebnis erst am Ende']],
    ['V-Modell', ['Wasserfall + Testzuordnung', 'Entwurf links, Tests rechts', 'Jede Teststufe prüft eine Entwurfsstufe', 'Üblich bei Behörden und sicherheitskritischer Software']],
    ['Agil', ['Iterativ und inkrementell', 'Anforderungen dürfen sich ändern', 'Regelmäßiges Kundenfeedback', 'Weniger Dokumentation, mehr Zusammenarbeit']],
    ['Wann welches Modell?', ['Anforderungen stabil: klassisch', 'Anforderungen unklar: agil', 'Festpreis und Vertrag: eher klassisch', 'Neues Produkt, Markt unsicher: agil']],
  ],
  blocks: [
    ['h', 'Warum braucht man Vorgehensmodelle?'],
    ['p', 'Software zu bauen ist komplex. Ohne Regeln arbeiten alle durcheinander, wichtige Schritte (zum Beispiel Tests) werden vergessen und niemand weiß, wie weit das Projekt ist. Ein Vorgehensmodell ist wie ein **Bauplan für den Ablauf**: Es sagt, welche Schritte es gibt und in welcher Reihenfolge sie passieren.'],
    ['h', 'Wasserfallmodell'],
    ['p', 'Das Wasserfallmodell ist das einfachste Modell. Jede Phase muss **komplett fertig** sein, bevor die nächste beginnt. Man geht nicht (oder nur sehr schwer) zurück. Daher der Name: Wasser fließt nur nach unten.'],
    ['diagram', {w: 720, h: 330, cap: 'Wasserfallmodell: Jede Phase beginnt erst, wenn die vorherige abgeschlossen ist.', nodes: [
      {id: 'a', x: 100, y: 34, t: 'Anforderungen', w: 160, h: 40, s: 'accent', k: 'round'},
      {id: 'b', x: 240, y: 96, t: 'Entwurf', w: 160, h: 40, s: 'accent', k: 'round'},
      {id: 'c', x: 380, y: 158, t: 'Implementierung', w: 160, h: 40, s: 'accent', k: 'round'},
      {id: 'd', x: 520, y: 220, t: 'Test', w: 160, h: 40, s: 'accent', k: 'round'},
      {id: 'e', x: 620, y: 282, t: 'Betrieb und Wartung', w: 190, h: 40, s: 'solid', k: 'round'},
    ], edges: [{a: 'a', b: 'b'}, {a: 'b', b: 'c'}, {a: 'c', b: 'd'}, {a: 'd', b: 'e'}]}],
    ['procon', 'Wasserfallmodell bewerten', ['Einfach zu verstehen und zu planen', 'Klare Phasen und Dokumente, gute Nachvollziehbarkeit', 'Gut bei stabilen Anforderungen und festem Budget'], ['Änderungswünsche sind spät sehr teuer', 'Kunde sieht erst am Ende ein Ergebnis', 'Fehler in der Anforderungsphase fallen oft erst beim Test auf']],
  ],
});
;
// content/ps/vorgehen-2.js
AP2.add('ps-vorgehen', [
  ['h', 'V-Modell'],
  ['p', 'Das V-Modell erweitert den Wasserfall. Auf der **linken Seite** wird die Software immer genauer entworfen (von grob nach fein). Auf der **rechten Seite** wird sie getestet (von klein nach groß). Der wichtige Gedanke: **Jede Entwurfsstufe hat eine passende Teststufe.** Was in der Anforderungsanalyse festgelegt wurde, prüft am Ende der Abnahmetest.'],
  ['diagram', {w: 760, h: 380, keep: 640, cap: 'V-Modell: Die gestrichelten Linien zeigen, welche Teststufe welche Entwurfsstufe prüft (Verifikation und Validierung).', nodes: [
    {id: 'l1', x: 100, y: 40, t: 'Anforderungsanalyse', s: 'accent', k: 'round', w: 176, h: 42},
    {id: 'l2', x: 190, y: 120, t: 'Systementwurf', s: 'accent', k: 'round', w: 176, h: 42},
    {id: 'l3', x: 280, y: 200, t: 'Komponentenentwurf', s: 'accent', k: 'round', w: 176, h: 42},
    {id: 'l4', x: 380, y: 300, t: 'Implementierung (Code)', s: 'solid', k: 'round', w: 200, h: 46},
    {id: 'r3', x: 480, y: 200, t: 'Modultest (Unit)', s: 'ok', k: 'round', w: 176, h: 42},
    {id: 'r2', x: 570, y: 120, t: 'Integrationstest', s: 'ok', k: 'round', w: 176, h: 42},
    {id: 'r1', x: 660, y: 40, t: 'Abnahmetest', s: 'ok', k: 'round', w: 176, h: 42},
  ], edges: [
    {a: 'l1', b: 'l2'}, {a: 'l2', b: 'l3'}, {a: 'l3', b: 'l4'}, {a: 'l4', b: 'r3'}, {a: 'r3', b: 'r2'}, {a: 'r2', b: 'r1'},
    {a: 'l1', b: 'r1', k: 'dash', ea: 'none', t: 'prüft gegen Anforderungen'}, {a: 'l2', b: 'r2', k: 'dash', ea: 'none'}, {a: 'l3', b: 'r3', k: 'dash', ea: 'none'},
  ]}],
  ['table', ['Entwurfsstufe (links)', 'Teststufe (rechts)', 'Prüft ...'], [
    ['Anforderungsanalyse (Lastenheft)', 'Abnahmetest (beim Kunden)', 'Erfüllt das System die Wünsche des Kunden?'],
    ['Systementwurf (Pflichtenheft, Architektur)', 'Systemtest / Integrationstest', 'Funktioniert das Gesamtsystem wie entworfen?'],
    ['Komponentenentwurf (Module, Klassen)', 'Modultest / Unit-Test', 'Funktioniert jedes einzelne Modul korrekt?'],
  ]],
  ['tip', 'Das V-Modell XT ist der Standard für Projekte der öffentlichen Hand in Deutschland. Das Wort "V" kommt von der Form: links runter (entwerfen), rechts rauf (testen).'],
  ['h', 'Weitere klassische Modelle in Kürze'],
  ['kv', [
    ['Spiralmodell', 'Wiederholte Zyklen aus Zielsetzung, Risikoanalyse, Entwicklung und Bewertung. Stärke: Risiken werden früh behandelt. Für große, riskante Projekte.'],
    ['Prototyping', 'Früh ein ausführbares Muster bauen, damit der Kunde reagieren kann. Gut, wenn Anforderungen unklar sind. Gefahr: Der Prototyp wird versehentlich zum Produkt.'],
    ['Iterativ / inkrementell', 'Iterativ: etwas immer wieder verbessern. Inkrementell: Funktion für Funktion Stück für Stück liefern. Grundlage der agilen Modelle.'],
  ]],
  ['h', 'Agile Modelle'],
  ['p', 'Agile Methoden (zum Beispiel **Scrum** und **Kanban**) gehen davon aus, dass sich Anforderungen ändern. Statt alles am Anfang zu planen, wird in kurzen **Iterationen (Sprints)** gearbeitet. Nach jedem Sprint gibt es ein **lauffähiges Teilprodukt** und Feedback vom Kunden. Das Agile Manifest betont: Menschen und Zusammenarbeit vor Prozessen, funktionierende Software vor umfassender Dokumentation, Zusammenarbeit mit dem Kunden vor Vertragsverhandlung, Reagieren auf Veränderung vor dem Befolgen eines Plans.'],
  ['procon', 'Klassisch (Wasserfall/V-Modell) oder agil?', ['**Klassisch:** gute Planbarkeit von Kosten und Terminen', '**Klassisch:** passt zu Festpreisverträgen und Zulassungen', '**Agil:** schnelle Reaktion auf Änderungen', '**Agil:** früher Nutzen durch frühe Auslieferung'], ['**Klassisch:** Änderungen spät teuer, Kunde sieht Ergebnis spät', '**Agil:** Aufwand und Endtermin schwerer vorab festzulegen', '**Agil:** braucht aktive Mitarbeit des Kunden und selbstorganisierte Teams', '**Agil:** weniger Dokumentation kann ein Problem werden']],
  ['h', 'Aufgaben im Prüfungsstil'],
  ['qa', 'Ein Kunde möchte eine Software, deren Funktionen er noch nicht genau beschreiben kann. Welches Vorgehensmodell empfehlen Sie und warum?', 'Ein agiles Vorgehen (zum Beispiel Scrum). Da die Anforderungen unklar sind und sich ändern werden, liefert man in kurzen Sprints lauffähige Teile, holt regelmäßig Feedback ein und passt die Planung an. Ein Wasserfallmodell wäre riskant, weil Fehler in den Anforderungen erst spät auffallen.', 4],
  ['qa', 'Nennen Sie die Stufen des V-Modells und ordnen Sie jeder Entwurfsstufe eine Teststufe zu.', ['- Anforderungsanalyse: Abnahmetest', '- Systementwurf: System- bzw. Integrationstest', '- Komponentenentwurf: Modultest', '- Ganz unten liegt die Implementierung.'], 4],
  ['quiz', [
    {q: 'Was ist das wichtigste Merkmal des Wasserfallmodells?', o: ['Phasen laufen strikt nacheinander.', 'Es wird in kurzen Sprints gearbeitet.', 'Der Kunde ist ständig im Team.', 'Es gibt keine Dokumente.'], a: 0, e: 'Wasserfall: Eine Phase muss fertig sein, bevor die nächste startet.'},
    {q: 'Welche Teststufe prüft im V-Modell die Anforderungsanalyse?', o: ['Abnahmetest', 'Modultest', 'Integrationstest', 'Kompiliertest'], a: 0, e: 'Der Abnahmetest prüft gegen die ursprünglichen Anforderungen des Kunden.'},
    {q: 'Für welche Situation sind agile Modelle besonders gut geeignet?', o: ['Anforderungen ändern sich häufig.', 'Alle Anforderungen sind fix und für Jahre unveränderlich.', 'Es gibt keinen Kunden.', 'Es darf kein Feedback geben.'], a: 0, e: 'Agil reagiert auf Änderungen durch kurze Iterationen und häufiges Feedback.'},
    {q: 'Was ist ein Nachteil des Wasserfallmodells?', o: ['Änderungen sind spät sehr teuer.', 'Es gibt zu viele Meetings.', 'Es kann nicht dokumentiert werden.', 'Es braucht keine Planung.'], a: 0, e: 'Weil Phasen abgeschlossen werden, sind spätere Änderungen aufwendig.'},
  ]],
]);
;
// content/ps/stakeholder-1.js
AP2.page('ps-stakeholder', {
  b: 'ps', g: 'Projektmanagement', t: 'Stakeholder- und Risikoanalyse, magisches Dreieck',
  d: 'Die **Stakeholderanalyse** ermittelt alle Personen und Gruppen, die ein Projekt **beeinflussen oder davon betroffen** sind, und bewertet sie nach **Einfluss** und **Interesse**. Die **Risikoanalyse** bewertet mögliche Störungen nach **Eintrittswahrscheinlichkeit** und **Schadenshöhe** und plant Gegenmaßnahmen. Das **magische Dreieck** zeigt, dass **Kosten, Zeit und Qualität (Leistungsumfang)** voneinander abhängen.',
  m: '**Stakeholder: Wer? Wie mächtig? Wie interessiert?** Hoch/hoch: **eng einbinden**. Hoher Einfluss, wenig Interesse: **zufriedenstellen**. Wenig Einfluss, hohes Interesse: **informieren**. Beides gering: **beobachten**. **Risiko = Wahrscheinlichkeit mal Schaden.** Dreieck: **eine Ecke ziehen, die anderen geben nach.**',
  cheat: [
    ['Stakeholder', ['**intern:** Geschäftsleitung, Fachabteilung, IT, Betriebsrat, Projektteam', '**extern:** Kunde, Lieferant, Dienstleister, Behörde, Datenschutzaufsicht', 'Bewertung: **Einfluss** (Macht) und **Interesse** (Betroffenheit)', 'Ergebnis: Stakeholder-Matrix (Portfolio, 4 Felder)']],
    ['Strategien (Matrix)', ['Einfluss hoch, Interesse hoch: **aktiv managen, eng einbinden**', 'Einfluss hoch, Interesse gering: **zufriedenstellen, früh informieren**', 'Einfluss gering, Interesse hoch: **regelmäßig informieren**', 'Einfluss gering, Interesse gering: **beobachten**']],
    ['Risikomanagement', ['1. Risiken **identifizieren**', '2. **bewerten** (W mal S)', '3. **Maßnahmen**: vermeiden, vermindern, übertragen, akzeptieren', '4. **überwachen**', 'Darstellung: **Risikomatrix** (Heatmap)']],
    ['Magisches Dreieck', ['**Zeit** (Termine), **Kosten** (Budget), **Qualität/Umfang** (Leistung)', 'Weniger Zeit kostet Geld oder Qualität', 'Mehr Qualität braucht Zeit oder Geld', 'Erweitert: **Teufelsquadrat** mit Umfang']],
  ],
  blocks: [
    ['h', 'Warum Stakeholder analysieren?'],
    ['p', 'Projekte scheitern selten an der Technik, sondern an **Menschen**: Ein übergangener Betriebsrat blockiert die Einführung, die Fachabteilung fühlt sich nicht gehört, der Datenschutzbeauftragte meldet zu spät Bedenken an. Die Stakeholderanalyse macht diese Beteiligten **vor** Projektbeginn sichtbar, damit man sie gezielt einbinden kann. Sie gehört in die **Initialisierungs- und Planungsphase**.'],
    ['steps', ['**Identifizieren:** Wer ist betroffen oder hat Einfluss? (Brainstorming, Organigramm, Checkliste intern/extern)', '**Bewerten:** Einfluss (Macht, Entscheidungsbefugnis) und Interesse (Betroffenheit) jeweils hoch oder gering einschätzen, Haltung notieren (Befürworter, Gegner, neutral).', '**Einordnen:** in die Stakeholder-Matrix eintragen.', '**Maßnahmen planen:** je Feld eine Kommunikationsstrategie festlegen (zum Beispiel Lenkungsausschuss, Workshop, Newsletter).', '**Fortschreiben:** Stakeholder ändern sich im Projekt; die Analyse regelmäßig aktualisieren.']],
    ['h', 'Die Stakeholder-Matrix'],
    ['diagram', {w: 700, h: 380, cap: 'Stakeholder-Matrix (Einfluss-Interesse-Portfolio) mit Beispielen für die Einführung eines Intranet-Informationssystems', nodes: [
      {id: 'q1', x: 230, y: 110, w: 300, h: 150, k: 'box', s: 'soft', t: ['Zufriedenstellen', '(früh informieren)', 'Geschäftsleitung, Datenschutz']},
      {id: 'q2', x: 530, y: 110, w: 300, h: 150, k: 'box', s: 'accent', t: ['Eng einbinden', '(aktiv managen)', 'IT-Abteilung, Betriebsrat']},
      {id: 'q3', x: 230, y: 260, w: 300, h: 150, k: 'box', s: 'plain', t: ['Beobachten', '(geringer Aufwand)', 'Lieferant der Hardware']},
      {id: 'q4', x: 530, y: 260, w: 300, h: 150, k: 'box', s: 'soft', t: ['Informieren', '(regelmäßig, Newsletter)', 'Mitarbeitende, Marketing']},
      {id: 'y', x: 40, y: 185, k: 'text', t: 'Einfluss', fs: 13, b: true},
      {id: 'x', x: 380, y: 360, k: 'text', t: 'Interesse', fs: 13, b: true},
      {id: 'yl', x: 60, y: 60, k: 'text', t: 'hoch', fs: 11}, {id: 'yh', x: 60, y: 320, k: 'text', t: 'gering', fs: 11},
      {id: 'xl', x: 110, y: 355, k: 'text', t: 'gering', fs: 11}, {id: 'xh', x: 655, y: 355, k: 'text', t: 'hoch', fs: 11},
    ], edges: [{a: [80, 340], b: [80, 30], w: 1.5}, {a: [80, 340], b: [695, 340], w: 1.5}]}],
    ['tip', 'In der Prüfung genügt oft: **zwei interne, zwei externe Stakeholder nennen, in die Matrix einordnen und je eine Maßnahme begründen.** Wichtig ist die Begründung, warum ein Stakeholder dort steht (zum Beispiel: Der Betriebsrat hat bei technischen Einrichtungen zur Leistungs- und Verhaltenskontrolle ein **Mitbestimmungsrecht** nach § 87 BetrVG, also hohen Einfluss).'],
    ['h', 'Risikoanalyse und Risikomatrix'],
    ['p', 'Ein **Risiko** ist ein mögliches Ereignis mit negativer Auswirkung auf Zeit, Kosten oder Qualität. Man bewertet es mit zwei Größen: **Eintrittswahrscheinlichkeit (W)** und **Schadensausmaß (S)**. Das Produkt ergibt die **Risikopriorität**. Je weiter rechts oben ein Risiko in der Matrix steht, desto dringender braucht es eine Maßnahme.'],
    ['diagram', {w: 640, h: 330, cap: 'Risikomatrix (Heatmap): rot = sofort handeln, gelb = beobachten und vorbeugen, grün = akzeptieren', nodes: [
      {id: 'a1', x: 190, y: 70, w: 140, h: 70, k: 'box', s: 'gold', t: 'mittel'}, {id: 'a2', x: 340, y: 70, w: 140, h: 70, k: 'box', s: 'bad', t: 'hoch'}, {id: 'a3', x: 490, y: 70, w: 140, h: 70, k: 'box', s: 'bad', t: 'sehr hoch'},
      {id: 'b1', x: 190, y: 145, w: 140, h: 70, k: 'box', s: 'ok', t: 'gering'}, {id: 'b2', x: 340, y: 145, w: 140, h: 70, k: 'box', s: 'gold', t: 'mittel'}, {id: 'b3', x: 490, y: 145, w: 140, h: 70, k: 'box', s: 'bad', t: 'hoch'},
      {id: 'c1', x: 190, y: 220, w: 140, h: 70, k: 'box', s: 'ok', t: 'sehr gering'}, {id: 'c2', x: 340, y: 220, w: 140, h: 70, k: 'box', s: 'ok', t: 'gering'}, {id: 'c3', x: 490, y: 220, w: 140, h: 70, k: 'box', s: 'gold', t: 'mittel'},
      {id: 'yl', x: 70, y: 70, k: 'text', t: 'W hoch', fs: 12}, {id: 'ym', x: 70, y: 145, k: 'text', t: 'W mittel', fs: 12}, {id: 'yn', x: 70, y: 220, k: 'text', t: 'W niedrig', fs: 12},
      {id: 'xn', x: 190, y: 285, k: 'text', t: 'Schaden niedrig', fs: 12}, {id: 'xm', x: 340, y: 285, k: 'text', t: 'Schaden mittel', fs: 12}, {id: 'xh', x: 490, y: 285, k: 'text', t: 'Schaden hoch', fs: 12},
    ], edges: []}],
    ['table', ['Risiko (Beispiel)', 'W', 'S', 'Maßnahme'], [
      ['Mitarbeitende lehnen das neue System ab', 'mittel', 'hoch', 'Früh informieren, Schulungen und Workshops, Key-User einbinden'],
      ['Externe Agentur liefert das Design zu spät', 'mittel', 'hoch', 'Puffer einplanen, Vertragsstrafe vereinbaren, regelmäßige Abstimmungstermine'],
      ['Datenschutzbedenken stoppen das Projekt', 'niedrig', 'hoch', 'Datenschutzbeauftragten von Beginn an beteiligen, Verarbeitungsverzeichnis anlegen'],
      ['Schlüsselentwickler fällt aus', 'niedrig', 'mittel', 'Wissen dokumentieren, Pair Programming, Vertretung regeln'],
    ]],
    ['kv', [
      ['Vermeiden', 'Ursache beseitigen, zum Beispiel auf eine unerprobte Technologie verzichten.'],
      ['Vermindern', 'Wahrscheinlichkeit oder Schaden senken, zum Beispiel Tests, Schulungen, Backups.'],
      ['Übertragen', 'Risiko an Dritte abgeben, zum Beispiel Versicherung, Festpreisvertrag, Outsourcing.'],
      ['Akzeptieren', 'Bewusst tragen, wenn die Maßnahme teurer wäre als der erwartete Schaden; Rücklage bilden.'],
    ]],
    ['h', 'Das magische Dreieck des Projektmanagements'],
    ['diagram', {w: 560, h: 300, cap: 'Magisches Dreieck: Die drei Zielgrößen konkurrieren. Verbessert man eine, leidet mindestens eine andere.', nodes: [
      {id: 'q', x: 280, y: 40, k: 'round', s: 'accent', t: 'Qualität / Leistung', w: 170},
      {id: 'z', x: 90, y: 250, k: 'round', s: 'accent', t: 'Zeit (Termine)', w: 150},
      {id: 'k', x: 470, y: 250, k: 'round', s: 'accent', t: 'Kosten (Budget)', w: 150},
      {id: 'm', x: 280, y: 170, k: 'text', t: ['Projekt-', 'erfolg'], fs: 14, b: true},
    ], edges: [{a: 'q', b: 'z', ea: 'none', sa: 'none'}, {a: 'z', b: 'k', ea: 'none'}, {a: 'k', b: 'q', ea: 'none'}]}],
    ['ex', ['Der Kunde verlangt den Go-live zwei Wochen früher (**Zeit** sinkt). Möglichkeiten: zusätzliche Entwickler einsetzen (**Kosten** steigen) oder Funktionen streichen bzw. weniger testen (**Qualität** sinkt). Alle drei gleichzeitig zu halten, ist nicht möglich.']],
    ['h', 'Aufgaben im Prüfungsstil'],
    ['qa', 'Für die Einführung eines neuen Ticketsystems bei einem Kunden mit 350 Mitarbeitenden sollen Sie eine Stakeholderanalyse vorbereiten. Nennen Sie je zwei interne und zwei externe Stakeholder.', ['- **Intern:** IT-Abteilung (Betrieb und Support), Betriebsrat (Mitbestimmung bei Leistungs- und Verhaltenskontrolle), Geschäftsleitung (Budget), Fachabteilungen als Anwender.', '- **Extern:** Softwarehersteller oder Dienstleister, Hosting-Anbieter, Kunden des Unternehmens (bekommen schnellere Antworten), Datenschutzaufsichtsbehörde.'], 4],
    ['qa', 'Beschreiben Sie je eine Maßnahme für den Umgang mit Stakeholdern mit (a) hohem Einfluss und hohem Interesse sowie (b) hohem Einfluss und geringem Interesse.', ['a) **Eng einbinden:** zum Beispiel im Lenkungsausschuss vertreten, regelmäßige Abstimmungstermine, an Entscheidungen beteiligen; so werden Widerstände früh erkannt.', 'b) **Zufriedenstellen:** kurz, früh und zielgerichtet informieren (zum Beispiel Statusbericht), Zustimmung zu wichtigen Meilensteinen einholen, ohne sie mit Details zu belasten.'], 4],
    ['qa', 'Erläutern Sie das magische Dreieck des Projektmanagements an einem Beispiel.', 'Das magische Dreieck beschreibt die Abhängigkeit der Zielgrößen **Zeit, Kosten und Qualität (Leistungsumfang)**. Ändert sich eine Größe, müssen die anderen angepasst werden. Beispiel: Soll das Projekt mit **weniger Budget** auskommen, verlängert sich die **Dauer** (weniger Personal) oder die **Qualität** sinkt (weniger Funktionen, weniger Tests).', 3],
    ['qa', 'Ein Risiko hat eine Eintrittswahrscheinlichkeit von 20 Prozent und einen möglichen Schaden von 40.000 Euro. Eine Gegenmaßnahme kostet 5.000 Euro und halbiert die Wahrscheinlichkeit. Lohnt sie sich?', ['Erwarteter Schaden ohne Maßnahme: 0,20 mal 40.000 = **8.000 Euro**.', 'Mit Maßnahme: 0,10 mal 40.000 = 4.000 Euro, plus Kosten 5.000 Euro = **9.000 Euro**.', 'Rein rechnerisch lohnt sich die Maßnahme **nicht** (9.000 Euro größer als 8.000 Euro). Man würde das Risiko eher akzeptieren oder eine günstigere Maßnahme suchen, es sei denn, der Schaden ist existenzbedrohend.'], 4],
    ['see', ['ps-phasen', 'ps-orga', 'ps-scrum', 'wiso-betriebsrat']],
    ['quiz', [
      {q: 'Wie behandelt man Stakeholder mit hohem Einfluss und hohem Interesse?', o: ['Eng einbinden und aktiv managen', 'Nur beobachten', 'Gar nicht informieren', 'Erst nach Projektende befragen'], a: 0, e: 'Sie können das Projekt stark fördern oder blockieren und sind betroffen, deshalb werden sie eng eingebunden.'},
      {q: 'Welche zwei Größen bewertet die Risikoanalyse?', o: ['Eintrittswahrscheinlichkeit und Schadensausmaß', 'Einfluss und Interesse', 'Kosten und Nutzen', 'Dauer und Puffer'], a: 0, e: 'Risikopriorität = Wahrscheinlichkeit mal Schaden. Einfluss und Interesse gehören zur Stakeholderanalyse.'},
      {q: 'Welche Ecken hat das magische Dreieck?', o: ['Zeit, Kosten, Qualität', 'Planung, Durchführung, Abschluss', 'Vertraulichkeit, Integrität, Verfügbarkeit', 'Team, Kunde, Lieferant'], a: 0, e: 'Zeit, Kosten und Qualität (Leistungsumfang) beeinflussen sich gegenseitig.'},
      {q: 'Ein Unternehmen schließt eine Versicherung gegen Datenverlust ab. Welche Risikostrategie ist das?', o: ['Übertragen', 'Vermeiden', 'Akzeptieren', 'Ignorieren'], a: 0, e: 'Das finanzielle Risiko wird an den Versicherer übertragen.'},
      {q: 'Welcher Stakeholder ist intern?', o: ['Der Betriebsrat', 'Der Softwarelieferant', 'Die Datenschutzaufsichtsbehörde', 'Ein externer Berater'], a: 0, e: 'Der Betriebsrat ist Teil des Unternehmens. Lieferanten, Behörden und Berater sind extern.'},
      {q: 'Wann wird die Stakeholderanalyse vor allem erstellt?', o: ['Zu Projektbeginn (Initialisierung/Planung) und laufend aktualisiert', 'Erst beim Projektabschluss', 'Nur bei Scrum-Projekten', 'Nur wenn es Probleme gibt'], a: 0, e: 'Früh, damit Kommunikation geplant werden kann; im Projektverlauf wird sie fortgeschrieben.'},
      {q: 'Der Kunde will mehr Funktionen bei gleichem Termin. Was folgt laut magischem Dreieck?', o: ['Die Kosten steigen (mehr Personal) oder die Qualität sinkt', 'Nichts ändert sich', 'Das Projekt wird automatisch günstiger', 'Die Dauer sinkt'], a: 0, e: 'Mehr Leistung in gleicher Zeit erfordert mehr Ressourcen oder geht zu Lasten der Qualität.'},
    ]],
  ],
});
;
// content/ps/netzplan-1.js
AP2.page('ps-netzplan', {
  b: 'ps', g: 'Projektmanagement', t: 'Netzplantechnik',
  d: 'Ein **Netzplan** stellt alle Vorgänge eines Projekts und ihre Abhängigkeiten als Netz dar. Mit **Vorwärtsrechnung** (früheste Zeiten) und **Rückwärtsrechnung** (späteste Zeiten) findet man die **Gesamtdauer**, die **Puffer** und den **kritischen Pfad**. Der kritische Pfad ist der längste Weg durch das Netz: Eine Verzögerung dort verschiebt das Projektende.',
  m: '**Vorwärts: FAZ = max der Vorgänger-FEZ, FEZ = FAZ + Dauer. Rückwärts: SEZ = min der Nachfolger-SAZ, SAZ = SEZ - Dauer.** Beim Zusammenlaufen vorwärts das **Maximum**, rückwärts das **Minimum**. Kritisch heißt: Gesamtpuffer = 0.',
  cheat: [
    ['Abkürzungen', ['**D** = Dauer', '**FAZ / FEZ** = frühester Anfangs- / Endzeitpunkt', '**SAZ / SEZ** = spätester Anfangs- / Endzeitpunkt', '**GP** = Gesamtpuffer, **FP** = freier Puffer']],
    ['Vorwärtsrechnung', ['Start: FAZ = 0 (erster Vorgang)', 'FEZ = FAZ + D', 'FAZ des Nachfolgers = FEZ des Vorgängers', 'Mehrere Vorgänger: **größter** FEZ zählt']],
    ['Rückwärtsrechnung', ['Start: SEZ letzter Vorgang = sein FEZ', 'SAZ = SEZ - D', 'SEZ des Vorgängers = SAZ des Nachfolgers', 'Mehrere Nachfolger: **kleinster** SAZ zählt']],
    ['Puffer', ['**GP = SAZ - FAZ** (oder SEZ - FEZ)', '**FP = kleinster FAZ der Nachfolger - FEZ**', 'GP = 0: kritischer Vorgang', 'Kritischer Pfad: Kette aus Vorgängen mit GP = 0']],
  ],
  blocks: [
    ['h', 'Wozu braucht man einen Netzplan?'],
    ['p', 'Ein einfacher Terminplan sagt nur: "Aufgabe A dauert 3 Tage." Ein Netzplan sagt zusätzlich: **Welche Aufgaben müssen vorher fertig sein?** Dadurch erkennt man, welche Aufgaben parallel laufen können, wie lange das Projekt mindestens dauert und welche Aufgaben **nicht** verspätet werden dürfen.'],
    ['p', 'Netzpläne werden nach der **Vorgangsknoten-Methode** (CPM, Critical Path Method) gezeichnet: Jeder **Vorgang** ist ein Kasten (Knoten), die Pfeile zeigen die Reihenfolge. Die Prüfung arbeitet fast immer mit dieser Darstellung.'],
    ['h', 'Wichtige Begriffe'],
    ['table', ['Begriff', 'Abkürzung', 'Bedeutung'], [
      ['Vorgang', 'V', 'Eine Aufgabe mit Dauer, zum Beispiel "Datenbank entwerfen".'],
      ['Dauer', 'D', 'Wie lange der Vorgang dauert (Tage, Wochen, Stunden).'],
      ['Frühester Anfangszeitpunkt', 'FAZ', 'Frühestens wann kann der Vorgang starten?'],
      ['Frühester Endzeitpunkt', 'FEZ', 'Frühestens wann kann er fertig sein? FEZ = FAZ + D.'],
      ['Spätester Anfangszeitpunkt', 'SAZ', 'Spätestens wann muss er starten, damit das Projektende hält?'],
      ['Spätester Endzeitpunkt', 'SEZ', 'Spätestens wann muss er fertig sein? SEZ = SAZ + D.'],
      ['Gesamtpuffer', 'GP', 'Um wie viel darf sich der Vorgang verzögern, ohne das Projektende zu verschieben?'],
      ['Freier Puffer', 'FP', 'Um wie viel darf er sich verzögern, ohne dass der **nächste** Vorgang später starten muss?'],
      ['Kritischer Vorgang', '-', 'Ein Vorgang mit GP = 0: kein Spielraum.'],
      ['Kritischer Pfad', '-', 'Kette aller kritischen Vorgänge von Start bis Ende. Bestimmt die Projektdauer.'],
    ]],
    ['h', 'So liest man einen Knoten'],
    ['diagram', {w: 560, h: 170, cap: 'Vorgangsknoten: oben und unten je 3 Felder, in der Mitte Nummer und Name.', nodes: [
      {id: 'n', k: 'np', x: 150, y: 80, w: 240, t: {nr: 'Nr.', name: 'Bezeichnung', d: 'D', faz: 'FAZ', fez: 'FEZ', saz: 'SAZ', sez: 'SEZ', gp: 'GP', fp: 'FP'}},
      {id: 'l1', k: 'text', x: 420, y: 38, t: 'Oben: früheste Zeiten (vorwärts)', fs: 12},
      {id: 'l2', k: 'text', x: 420, y: 72, t: 'Unten: späteste Zeiten (rückwärts)', fs: 12},
      {id: 'l3', k: 'text', x: 420, y: 106, t: 'Mitte: oben Dauer, unten Gesamtpuffer', fs: 12},
      {id: 'l4', k: 'text', x: 420, y: 140, t: 'Links: Anfang, rechts: Ende', fs: 12},
    ], edges: []}],
    ['tip', '**Merkregel:** `FAZ | D | FEZ` oben, Nummer und Name in der Mitte, `SAZ | GP | SEZ` unten. Oben die **frühen**, unten die **späten** Zeiten; links der **Anfang**, rechts das **Ende**. In der Mitte steht oben die **Dauer** und unten der **Gesamtpuffer**. Der **freie Puffer (FP)** steht klein unter dem Knoten.'],
    ['h', 'Ablauf in vier Schritten'],
    ['steps', ['**Vorgänge und Abhängigkeiten** aus der Tabelle als Knoten und Pfeile zeichnen.', '**Vorwärts** von links nach rechts: FAZ und FEZ eintragen (bei Zusammenlauf das **Maximum**).', '**Rückwärts** von rechts nach links: SEZ und SAZ eintragen (bei Verzweigung das **Minimum**).', '**Puffer** berechnen (GP = SAZ - FAZ); Vorgänge mit GP = 0 bilden den **kritischen Pfad**.']],
    ['note', 'Ein Pfad ist eine Kette von Vorgängen von Start bis Ende. Seine Länge ist die Summe der Dauern. Der **längste Pfad** ist der kritische Pfad und bestimmt die Projektdauer. Pfade daneben haben Puffer.'],
  ],
});
;
// content/ps/netzplan-2.js
(function () {
  // Vorgangsknoten in Prüfungsform; phase 1 = nur Vorwärts, 2 = mit Rückwärts, 3 = komplett mit Puffern.
  const T = [['a', 'Analyse', 3, 0, 3, 0, 3, 0, 0, 1], ['b', 'Entwurf', 4, 3, 7, 3, 7, 0, 0, 1], ['c', 'Datenbank', 5, 7, 12, 7, 12, 0, 0, 1], ['e', 'Backend', 8, 12, 20, 12, 20, 0, 0, 1],
    ['f', 'Integration', 3, 20, 23, 20, 23, 0, 0, 1], ['g', 'Test', 4, 23, 27, 23, 27, 0, 0, 1], ['d', 'Oberfläche', 6, 7, 13, 14, 20, 7, 7, 0]];
  const X = {a: 90, b: 280, c: 470, e: 660, f: 850, g: 1040, d: 565};
  const net = (phase, cap) => ({w: 1130, h: 240, keep: 900, cap, nodes: T.map(([id, name, d, faz, fez, saz, sez, gp, fp, crit]) => ({id, k: 'np', x: X[id], y: id === 'd' ? 190 : 60,
    s: phase === 3 && crit ? 'accent' : 'plain', t: Object.assign({nr: id.toUpperCase(), name, d, faz, fez}, phase > 1 ? {saz, sez} : {}, phase > 2 ? {gp, fp} : {})})),
  edges: [{a: 'a', b: 'b'}, {a: 'b', b: 'c'}, {a: 'c', b: 'e'}, {a: 'e', b: 'f'}, {a: 'f', b: 'g'}, {a: 'b', b: 'd', via: [[280, 190]]}, {a: 'd', b: 'f', via: [[850, 190]]}]});
  AP2.add('ps-netzplan', [
    ['h', 'Schritt für Schritt: ein vollständiges Beispiel'],
    ['p', 'Ein Team entwickelt eine kleine Web-Anwendung. Die Vorgänge, ihre Dauern (in Tagen) und Vorgänger:'],
    ['table', ['Vorgang', 'Bezeichnung', 'Dauer', 'Vorgänger'], [['A', 'Analyse', '3', '-'], ['B', 'Entwurf', '4', 'A'], ['C', 'Datenbank', '5', 'B'], ['D', 'Oberfläche', '6', 'B'], ['E', 'Backend', '8', 'C'], ['F', 'Integration', '3', 'D, E'], ['G', 'Test', '4', 'F']]],
    ['h3', 'Schritt 1: Vorwärtsrechnung (früheste Zeiten)'],
    ['steps', ['**A** startet bei 0: FAZ = 0, FEZ = 0 + 3 = **3**.', '**B** startet, wenn A fertig ist: FAZ = 3, FEZ = 3 + 4 = **7**.', '**C** und **D** starten beide nach B: FAZ = 7. FEZ(C) = 7 + 5 = **12**, FEZ(D) = 7 + 6 = **13**.', '**E** startet nach C: FAZ = 12, FEZ = 12 + 8 = **20**.', '**F** hat zwei Vorgänger (D und E). Er kann erst starten, wenn **beide** fertig sind: FAZ = max(13, 20) = **20**. FEZ = 20 + 3 = **23**.', '**G** startet nach F: FAZ = 23, FEZ = 23 + 4 = **27**. Die Gesamtdauer des Projekts ist **27 Tage**.']],
    ['diagram', net(1, 'Nach der Vorwärtsrechnung: oben links FAZ, oben rechts FEZ. Bei F laufen D (FEZ 13) und E (FEZ 20) zusammen: das Maximum 20 zählt.')],
    ['h3', 'Schritt 2: Rückwärtsrechnung (späteste Zeiten)'],
    ['steps', ['Beim letzten Vorgang gilt: SEZ = FEZ = **27**. SAZ(G) = 27 - 4 = **23**.', '**F:** SEZ = SAZ(G) = 23, SAZ = 23 - 3 = **20**.', '**E:** SEZ = SAZ(F) = 20, SAZ = 20 - 8 = **12**.', '**D:** SEZ = SAZ(F) = 20, SAZ = 20 - 6 = **14**.', '**C:** SEZ = SAZ(E) = 12, SAZ = 12 - 5 = **7**.', '**B** hat zwei Nachfolger (C und D): SEZ = min(7, 14) = **7**. SAZ = 7 - 4 = **3**.', '**A:** SEZ = SAZ(B) = 3, SAZ = 3 - 3 = **0**. Das passt zum Start bei 0.']],
    ['diagram', net(2, 'Nach der Rückwärtsrechnung: unten links SAZ, unten rechts SEZ. Bei B laufen C und D auseinander: das Minimum der SAZ (7 und 14) zählt.')],
    ['h3', 'Schritt 3: Puffer und kritischer Pfad'],
    ['p', '**GP = SAZ - FAZ.** Nur Vorgang **D** hat Spielraum: GP(D) = 14 - 7 = **7**. Alle anderen haben GP = 0. Der **freie Puffer** von D ist FP = FAZ(F) - FEZ(D) = 20 - 13 = **7**.'],
    ['diagram', net(3, 'Fertiger Netzplan. Hervorgehoben: kritischer Pfad A, B, C, E, F, G mit 27 Tagen (GP = 0). Nur D hat Puffer.')],
    ['tip', 'Kritische Vorgänge erkennst du an **GP = 0**. Der kritische Pfad ist immer der **längste** Weg. Zur Kontrolle: A + B + C + E + F + G = 3 + 4 + 5 + 8 + 3 + 4 = 27. Der Weg über D wäre nur 3 + 4 + 6 + 3 + 4 = 20 lang.'],
    ['h', 'Was bedeutet das für das Projekt?'],
    ['list', ['**Verzögert sich C um 2 Tage**, endet das Projekt 2 Tage später (29 statt 27 Tage), denn C ist kritisch.', '**Verzögert sich D um 5 Tage**, passiert nichts: D hat 7 Tage Gesamtpuffer.', '**Verzögert sich D um 9 Tage**, endet das Projekt 2 Tage später (9 - 7 = 2).', 'Wer das Projekt beschleunigen will, muss **kritische** Vorgänge verkürzen (mehr Personal, Parallelisierung). Bei D zu sparen bringt nichts.']],
    ['warn', ['**Typische Fehler in der Prüfung:**', '- Bei mehreren Vorgängern beim Vorwärtsrechnen das **Minimum** statt des Maximums nehmen (richtig: Maximum).', '- Bei mehreren Nachfolgern beim Rückwärtsrechnen das Maximum statt des **Minimums** nehmen.', '- Dauer und Zeitpunkt verwechseln: FEZ = FAZ + D, nicht FAZ + D + 1 (außer die Aufgabe gibt eine andere Zählweise vor).', '- Den Puffer nur bei Vorgängen mit Nebenweg erwarten: Alle Vorgänge auf dem kritischen Pfad haben GP = 0.']],
    ['tool', 'netzplan'],
  ]);
})();
;
